// core.js:1058
function t(key) {
  return (KR_WORDS[currentLang] || KR_WORDS.en)[key] ?? KR_WORDS.en[key] ?? key;
}
// core.js:1437
function tf(key, vars = {}) { return t(key).replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m)); }
// core.js:1151
function esc(str) {
  if (str == null) return '';
  return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
// core.js:1417-1422
const ICON_ALIAS = { deals: 'kanban', contacts: 'users', tasks: 'check-square', suppliers: 'truck', chat: 'message', activities: 'activity',
  listings: 'building', objects: 'building', analytics: 'bar-chart', integrations: 'plug', board: 'presentation', workspaces: 'building', logout: 'log-out', more: 'ellipsis',
  call: 'phone', email: 'mail', whatsapp: 'message-circle', meeting: 'calendar' };
function icon(name, cls = '') { return `<svg class="ic ${cls}" aria-hidden="true"><use href="#i-${ICON_ALIAS[name] || name}"/></svg>`; }
// core.js:1427-1435
const AV_COLORS = ['#3D6DA9', '#0E7C86', '#6D5AE0', '#B45309', '#9D2B6B', '#2F7D32', '#5C6BC0', '#C2410C'];
function initialsOf(name) { return String(name || '').split(/\s+/).filter(Boolean).slice(0, 2).map(w => w[0]).join('').toUpperCase(); }
function hashColor(s) { return AV_COLORS[[...String(s || '')].reduce((a, c) => a + c.charCodeAt(0), 0) % AV_COLORS.length]; }
function avatar(who, size = '') {
  const p = typeof who === 'string' ? { name: who } : who;
  if (!p || !p.name) return '';
  return `<span class="avatar${size ? ' avatar-' + size : ''}" style="background:${p.color || hashColor(p.name)}" title="${esc(p.name)}">${esc(p.initials || initialsOf(p.name))}</span>`;
}
// deals.js:46-64
const DEAL_URGENCY = [
  { value: 0, label: 'No urgency',  color: 'transparent',    tone: 'neutral' },
  { value: 1, label: 'Low',         color: 'var(--success)', tone: 'neutral' },
  { value: 2, label: 'Medium',      color: 'var(--warning)', tone: 'info' },
  { value: 3, label: 'High',        color: '#f59e0b',        tone: 'warning' },
  { value: 4, label: 'Very urgent', color: 'var(--danger)',  tone: 'danger' },
];
function urgencyMeta(v) {
  const n = parseInt(v, 10) || 0;
  return DEAL_URGENCY.find(u => u.value === n) || DEAL_URGENCY[0];
}
function urgencyLabel(m) { const k = 'urg_' + m.value, s = t(k); return s === k ? m.label : s; }
function urgencyBadge(v) {
  const n = parseInt(v, 10) || 0;
  if (!n) return '';
  const m = urgencyMeta(n);
  return `<span class="badge badge-${m.tone}">${esc(urgencyLabel(m))}</span>`;
}
// deals.js:67-88
function fmtEUR(n) {
  return new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(Number(n) || 0);
}
function fmtEURShort(n) {
  const v = Number(n) || 0;
  if (v >= 1e6) return (v / 1e6).toLocaleString('en-US', { maximumFractionDigits: 2 }) + 'M €';
  if (v >= 1e3) return (v / 1e3).toLocaleString('en-US', { maximumFractionDigits: 2 }) + 'k €';
  return fmtEUR(v);
}
function fmtDateShort(ts) {
  if (!ts) return '';
  return new Date(ts).toLocaleDateString(currentLang === 'de' ? 'de-DE' : 'en-GB', { day: 'numeric', month: 'short' });
}
function agoDays(ts) {
  if (!ts) return '';
  const L = currentLang === 'de'
    ? { today: 'Heute', yesterday: 'Gestern', days: n => `vor ${n} Tagen`, week: 'vor 1 Woche', weeks: n => `vor ${n} Wochen`, months: n => `vor ${n} Monaten` }
    : { today: 'Today', yesterday: 'Yesterday', days: n => `${n} days ago`, week: '1 week ago', weeks: n => `${n} weeks ago`, months: n => `${n} months ago` };
  const day = x => { const d = new Date(x); d.setHours(0, 0, 0, 0); return d.getTime(); };
  const d = Math.max(0, Math.round((day(Date.now()) - day(ts)) / 86400000));
  return d === 0 ? L.today : d === 1 ? L.yesterday : d < 7 ? L.days(d) : d < 14 ? L.week : d < 60 ? L.weeks(Math.round(d / 7)) : L.months(Math.round(d / 30));
}


/* ════ shell ════ */
/* kr-shell.js — the app shell (sidebar, top bar, bell panel, toasts, menus, dialogs) as pure renderers.
   Concatenated after kr-core.js. Every template is the app's own (cited above each function), changed only by:
   inline handlers → data-kr="<action>" in the same place, ids → `${p}-<id>`, static index.html text → t(<key>)
   exactly as applyTranslations() (core.js:1069-1074) fills it. Proof: kr-shell.check.js. Notes: kr-shell.md. */

// The sidebar labels setCrumbs() reads back (core.js:1535-1540 takes `.sb-link[data-page] .sb-text`).
const KR_NAV_KEYS = { deals: 'nav_deals', contacts: 'nav_contacts', tasks: 'nav_tasks', chat: 'nav_chat', activities: 'nav_activities',
  calendar: 'nav_calendar', board: 'nav_board', analytics: 'nav_analytics', onboarding: 'nav_onboarding', integrations: 'nav_integrations', settings: 'nav_settings' };

// objects.js:75-76 supplierWord() / objectWord() with n omitted (the plural the sidebar shows)
function krShellSupplierWord(o) { return o.supplierName || t('ct_suppliers_fallback'); }
function krShellObjectWord(o) { return o.objectName || t('obj_listings_fallback'); }

// core.js:1535-1540 setCrumbs(page): the active link's .sb-text, trimmed; 'workspaces' has no link → t('nav_workspaces').
// o = the krSidebar options (active, supplierName, objectName). Pass the result to krTopbar({ crumb }).
function krCrumbFor(o = {}) {
  const page = o.active;
  if (page === 'suppliers') return krShellSupplierWord(o).trim();
  if (page === 'objects') return krShellObjectWord(o).trim();
  if (KR_NAV_KEYS[page]) return t(KR_NAV_KEYS[page]).trim();
  return page === 'workspaces' ? t('nav_workspaces') : String(page || '');
}

// clock.js:142-161 updateClock(): the sidebar clock text (12-hour en-US with seconds, in the user's zone). The app
// re-runs it every 1000 ms (clock.js:133-136) and writes it to #sidebar-clock.
function krClockText(date = new Date(), tz = 'Europe/Berlin') {
  try {
    return date.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true, timeZone: tz });
  } catch {
    return date.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true });
  }
}

// index.html:329-374 nav.sidebar, filled the way the app fills it:
//   core.js:1069-1074 applyTranslations · core.js:1550-1555 setSidebarWorkspace (name + badge) · auth.js:126-130 showApp
//   (user name, avatar letter, role) · clock.js:142-161 updateClock · objects.js:77-81 + 96-104 (supplier / object words)
//   objects.js:504 updateBoardNavVisibility · onboarding.js:25-31 updateOnboardingNav · chat.js:139-144 updateChatBadge
//   auth.js:536-538 switchPage (aria-current="page" on the active link only, appended as the link's last attribute).
// Deviation: the .brk-egg game button (index.html:371-372) and the source comments are left out.
function krSidebar(o = {}) {
  const p = o.p || 'kr', u = o.user || {};
  const ws = String(o.wsName || '');
  const badge = ws.split(/\s+/).filter(Boolean).slice(0, 2).map(w => w[0]).join('').toUpperCase() || '·';
  const avatarLetter = (u.name || '?')[0].toUpperCase();
  const role = u.role ? (t(`role_${u.role}`) === `role_${u.role}` ? u.role : t(`role_${u.role}`)) : '';
  const chat = o.chatCount || 0;
  const cur = page => (page === o.active ? ' aria-current="page"' : '');
  return `<nav class="sidebar" aria-label="${esc(t('html_nav_main'))}" data-i18n-aria="html_nav_main">
  <div class="sb-brand">
    <img src="/images/logo.png" alt="Upgrads" class="sb-full" />
    <button class="iconbtn sb-toggle" type="button" data-kr="rail" title="${esc(t('html_collapse_sidebar'))}" data-i18n-title="html_collapse_sidebar" aria-label="${esc(t('html_collapse_sidebar'))}" data-i18n-aria="html_collapse_sidebar"><svg class="ic" aria-hidden="true"><use href="#i-panel-left"/></svg></button>
  </div>

  <button class="sb-ws" id="${p}-ws-switcher" data-kr="workspaces" type="button" title="${esc(t('nav_workspaces'))}" data-i18n-title="nav_workspaces">
    <span class="sb-ws-badge" id="${p}-sidebar-workspace-badge">${esc(badge)}</span>
    <span class="grow">
      <span class="sb-ws-name" id="${p}-sidebar-workspace">${esc(ws)}</span>
      <span class="sidebar-clock sb-ws-meta" id="${p}-sidebar-clock" title="${esc(t('html_click_change_tz'))}" data-i18n-title="html_click_change_tz" data-kr="clock-tz">${esc(o.clock || '')}</span>
    </span>
    <span class="sb-chev"><svg class="ic" aria-hidden="true"><use href="#i-chevrons-up-down"/></svg></span>
  </button>

  <div class="sb-scroll sidebar-main">
    <div class="sb-label" data-i18n="sb_workspace">${esc(t('sb_workspace'))}</div>
    <a href="#" class="sb-link" data-page="deals"${cur('deals')}><svg class="ic" aria-hidden="true"><use href="#i-kanban"/></svg><span class="sb-text" data-i18n="nav_deals">${esc(t('nav_deals'))}</span></a>
    <a href="#" class="sb-link" data-page="contacts"${cur('contacts')}><svg class="ic" aria-hidden="true"><use href="#i-users"/></svg><span class="sb-text" data-i18n="nav_contacts">${esc(t('nav_contacts'))}</span></a>
    <a href="#" class="sb-link" data-page="suppliers" id="${p}-nav-suppliers-link"${cur('suppliers')}><svg class="ic" aria-hidden="true"><use href="#i-truck"/></svg><span class="sb-text" id="${p}-nav-suppliers-label">${esc(krShellSupplierWord(o))}</span></a>
    <a href="#" class="sb-link" data-page="tasks"${cur('tasks')}><svg class="ic" aria-hidden="true"><use href="#i-check-square"/></svg><span class="sb-text" data-i18n="nav_tasks">${esc(t('nav_tasks'))}</span></a>

    <div class="sb-label" data-i18n="sb_tools">${esc(t('sb_tools'))}</div>
    <a href="#" class="sb-link" data-page="chat"${cur('chat')}><svg class="ic" aria-hidden="true"><use href="#i-message"/></svg><span class="sb-text" data-i18n="nav_chat">${esc(t('nav_chat'))}</span><span class="sb-count alert${chat === 0 ? ' hidden' : ''}" id="${p}-chat-badge">${chat > 99 ? '99+' : String(chat)}</span></a>
    <a href="#" class="sb-link" data-page="activities"${cur('activities')}><svg class="ic" aria-hidden="true"><use href="#i-activity"/></svg><span class="sb-text" data-i18n="nav_activities">${esc(t('nav_activities'))}</span></a>
    <a href="#" class="sb-link" data-page="calendar"${cur('calendar')}><svg class="ic" aria-hidden="true"><use href="#i-calendar"/></svg><span class="sb-text" data-i18n="nav_calendar">${esc(t('nav_calendar'))}</span></a>
    <a href="#" class="sb-link" data-page="objects" id="${p}-nav-objects-link"${cur('objects')}><svg class="ic" aria-hidden="true"><use href="#i-building"/></svg><span class="sb-text" id="${p}-nav-objects-label">${esc(krShellObjectWord(o))}</span></a>
    <a href="#" class="sb-link${o.showBoard ? '' : ' hidden'}" data-page="board" id="${p}-nav-board-link"${cur('board')}><svg class="ic" aria-hidden="true"><use href="#i-presentation"/></svg><span class="sb-text" data-i18n="nav_board">${esc(t('nav_board'))}</span></a>
    <a href="#" class="sb-link" data-page="analytics"${cur('analytics')}><svg class="ic" aria-hidden="true"><use href="#i-bar-chart"/></svg><span class="sb-text" data-i18n="nav_analytics">${esc(t('nav_analytics'))}</span></a>

    <a href="#" class="sb-link${o.showOnboarding ? '' : ' hidden'}" data-page="onboarding" id="${p}-nav-onboarding-link"${cur('onboarding')}><svg class="ic" aria-hidden="true"><use href="#i-target"/></svg><span class="sb-text" data-i18n="nav_onboarding">${esc(t('nav_onboarding'))}</span></a>
    <a href="#" class="sb-link" data-page="integrations"${cur('integrations')}><svg class="ic" aria-hidden="true"><use href="#i-plug"/></svg><span class="sb-text" data-i18n="nav_integrations">${esc(t('nav_integrations'))}</span></a>
  </div>

  <div class="sb-foot">
    <a href="#" class="sb-link" data-page="settings"${cur('settings')}><svg class="ic" aria-hidden="true"><use href="#i-settings"/></svg><span class="sb-text" data-i18n="nav_settings">${esc(t('nav_settings'))}</span></a>

    <button class="sb-user" id="${p}-sidebar-user-btn" data-kr="user-menu" type="button" aria-haspopup="menu">
      <span class="sidebar-user-avatar" id="${p}-sidebar-user-avatar">${esc(avatarLetter)}</span>
      <span class="who"><b id="${p}-sidebar-user">${esc(u.name || '')}</b><span id="${p}-sidebar-user-role">${esc(role)}</span></span>
    </button>
  </div>
</nav>`;
}

// index.html:377-385 header.topbar, filled by core.js:1535-1540 setCrumbs (always one <b>: no caller passes a trail),
// applyTranslations, and notifications.js:67-72 loadNotifications (badge "9+" above 9, class "hidden" at 0).
// crumb = the already-translated page title (krCrumbFor(sidebarOptions) gives the app's value).
function krTopbar(o = {}) {
  const p = o.p || 'kr', unread = o.bellCount || 0;
  return `<header class="topbar">
  <div class="crumbs" id="${p}-crumbs"><b>${esc(o.crumb)}</b></div>
  <button class="search-trigger" data-kr="palette" type="button" aria-label="${esc(t('html_search'))}" data-i18n-aria="html_search"><svg class="ic" aria-hidden="true"><use href="#i-search"/></svg><span class="grow" data-i18n="topbar_search">${esc(t('topbar_search'))}</span><span class="kbd-wrap"><span class="kbd">Ctrl K</span></span></button>
  <div class="topbar-actions">
    <button class="btn btn-primary" id="${p}-topbar-new-btn" data-kr="new-menu" type="button" aria-haspopup="menu"><svg class="ic" aria-hidden="true"><use href="#i-plus"/></svg><span data-i18n="topbar_new">${esc(t('topbar_new'))}</span></button>
    <button class="iconbtn" id="${p}-notif-bell-btn" data-kr="notif-toggle" type="button" aria-label="${esc(t('set_notifications'))}" data-i18n-aria="set_notifications" title="${esc(t('set_notifications'))}" data-i18n-title="set_notifications"><svg class="ic" aria-hidden="true"><use href="#i-bell"/></svg><span class="notif-badge${unread === 0 ? ' hidden' : ''}" id="${p}-notif-badge">${unread > 9 ? '9+' : String(unread)}</span></button>
    <button class="iconbtn" id="${p}-guide-help-btn" data-kr="help-menu" type="button" aria-label="${esc(t('html_help'))}" data-i18n-aria="html_help" title="${esc(t('html_help'))}" data-i18n-title="html_help" aria-haspopup="menu"><svg class="ic" aria-hidden="true"><use href="#i-help"/></svg></button>
  </div>
</header>`;
}

// notifications.js:29-43 NOTIF_ICONS / 45 NOTIF_KINDS / 47-48 notifIcon, notifKind / 50-59 notifTimeAgo
const KR_NOTIF_ICONS = {
  contact_created: '👤',
  deal_created:    '🤝',
  deal_updated:    '✏️',
  deal_stage_changed: '🔄',
  task_created:    '✅',
  system:          '🚀',
  mention:         '@',
  meeting_booked:    '📅',
  meeting_moved:     '🗓️',
  meeting_cancelled: '🚫',
  notetaker_done:    '📝',
  notetaker_failed:  '⚠️',
  default:         '🔔',
};
const KR_NOTIF_KINDS = { meeting_booked: 'notif_meeting_booked', meeting_moved: 'notif_meeting_moved', meeting_cancelled: 'notif_meeting_cancelled', notetaker_done: 'notif_notetaker_done', notetaker_failed: 'notif_notetaker_failed' };
function krNotifIcon(type) { return KR_NOTIF_ICONS[type] || KR_NOTIF_ICONS.default; }
function krNotifKind(type) { return KR_NOTIF_KINDS[type] ? `<div class="notif-kind">${esc(t(KR_NOTIF_KINDS[type]))}</div>` : ''; }
function krNotifTimeAgo(dateStr) {
  const diff = Date.now() - new Date(dateStr).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 1)   return t('ago_now');
  if (m < 60)  return tf('chat_ago_m', { n: m });
  const h = Math.floor(m / 60);
  if (h < 24)  return tf('ago_h', { n: h });
  const d = Math.floor(h / 24);
  return tf('ago_d', { n: d });
}

// notifications.js:77-99 renderNotifList(notifications): the inside of #notif-list (empty state, or one row per item).
// The row's onclick="onNotifClick(id, 'entity_type', entity_id)" becomes data-kr="notif-open" + data-kr-id /
// data-kr-entity-type / data-kr-entity-id ('' where the app passes '' / null).
function krNotifList(notifications) {
  if (!notifications.length) {
    return `<div class="notif-empty">
      <div style="font-size:32px;margin-bottom:8px">🔔</div>
      ${esc(t('notif_caught_up'))}<br>${esc(t('notif_appear_here'))}
    </div>`;
  }
  return notifications.map(n => `
    <div class="notif-item${n.read ? '' : ' unread'}${n.type === 'system' ? ' notif-system' : ''}"
      data-kr="notif-open" data-kr-id="${esc(n.id)}" data-kr-entity-type="${esc(n.entity_type || '')}" data-kr-entity-id="${esc(n.entity_id || '')}">
      <span class="notif-dot${n.read ? ' read' : ''}"></span>
      <span class="notif-icon">${krNotifIcon(n.type)}</span>
      <div class="notif-content">
        ${krNotifKind(n.type)}<div class="notif-title">${esc(n.title)}</div>
        ${n.body ? `<div class="notif-body">${esc(n.body)}</div>` : ''}
        ${n.actor_name ? `<div class="notif-body">${tf('notif_by', { name: esc(n.actor_name) })}</div>` : ''}
        <div class="notif-time">${krNotifTimeAgo(n.created_at)}</div>
      </div>
    </div>`).join('');
}

// index.html:388-398 #notif-panel as notifications.js:115-119 toggleNotifPanel opens it (class "hidden" dropped) and
// notifications.js:77-99 fills its list. Place it right AFTER krTopbar() inside .main (a sibling of the header).
// open: false gives the closed panel (class "hidden"); items omitted while closed = never opened (empty list).
function krBellPanel(o = {}) {
  const p = o.p || 'kr', open = o.open !== false;
  const items = o.items || (open ? [] : null);
  return `<div id="${p}-notif-panel" class="notif-panel${open ? '' : ' hidden'}">
  <div class="notif-panel-header">
    <span class="notif-panel-title" data-i18n="set_notifications">${esc(t('set_notifications'))}</span>
    <div style="display:flex;gap:6px;align-items:center">
      <button class="btn btn-sm btn-ghost" data-kr="notif-read-all" data-i18n="html_mark_all_read">${esc(t('html_mark_all_read'))}</button>
      <button class="btn btn-sm btn-ghost" data-kr="notif-clear" data-i18n="html_clear">${esc(t('html_clear'))}</button>
      <button class="iconbtn" data-kr="notif-toggle" aria-label="${esc(t('btn_close'))}" data-i18n-aria="btn_close" style="width:28px;height:28px"><svg class="ic" aria-hidden="true"><use href="#i-x"/></svg></button>
    </div>
  </div>
  <div id="${p}-notif-list" class="notif-list">${items ? krNotifList(items) : ''}</div>
</div>`;
}

// core.js:1523-1529 ui.toast: the .toasts wrapper (role="status" aria-live="polite") with one .toast per call, newest
// last; while 3 are showing the oldest is dropped before a new one goes in, so only the last 3 of `list` are drawn.
// list = [{ text, action }] (action = the button label or null). The button gets data-kr-toast="<index in list>".
function krToasts(list = []) {
  return `<div class="toasts" role="status" aria-live="polite">${list.map((x, i) => [x, i]).slice(-3).map(([x, i]) =>
    `<div class="toast"><span>${esc(x.text)}</span>${x.action ? `<button data-kr-toast="${i}">${esc(x.action)}</button>` : ''}</div>`).join('')}</div>`;
}

// core.js:1445-1447 ui.popover (the container: className || 'menu', inline width when given) + core.js:1472-1476
// ui.menu (the items and role="menu"). The inline left/top ui.popover computes (core.js:1450-1455) is NOT written:
// the page positions the menu. items: { label, icon?, hint?, checked?, danger? } | { sep: true } | { heading }.
// html instead of items = a bare ui.popover (no role="menu"), e.g. contacts.js:442-446.
function krMenu(o = {}) {
  const items = o.items || [];
  const html = o.html != null ? o.html : items.map((it, i) => it.sep ? '<div class="menu-sep"></div>' : it.heading ? `<div class="menu-label">${esc(it.heading)}</div>`
    : `<button class="menu-item ${it.danger ? 'danger' : ''}" role="menuitem" data-i="${i}">${it.icon ? icon(it.icon) : ''}<span>${esc(it.label)}</span>${it.hint ? `<span class="kbd" style="margin-left:auto">${esc(it.hint)}</span>` : ''}${it.checked ? icon('check', 'check-mark') : ''}</button>`).join('');
  return `<div class="${esc(o.className || 'menu')}"${o.width ? ` style="width: ${esc(o.width)}px;"` : ''}${o.html != null ? '' : ' role="menu"'}>${html}</div>`;
}

// The app's own menu item lists, without onSelect (`act` names what the item does; krMenu ignores it).
// core.js:1559-1567 openNewMenu — supplierName = the workspace's supplier word (null → t('core_supplier')), singular
function krNewMenuItems(supplierName) {
  const supplierLabel = (supplierName || t('core_supplier')).replace(/s$/i, '');
  return [
    { label: t('new_deal'), icon: 'deals', act: 'new-deal' },
    { label: t('new_contact'), icon: 'contacts', act: 'new-contact' },
    { label: supplierLabel, icon: 'suppliers', act: 'new-supplier' },
    { label: t('new_task'), icon: 'tasks', act: 'new-task' },
  ];
}
// core.js:1569-1573 openHelpMenu — the tour item only while the admin console enables it
function krHelpMenuItems(tourEnabled = false) {
  const items = [{ label: t('kbd_shortcuts'), icon: 'keyboard', act: 'shortcuts' }];
  if (tourEnabled) items.push({ label: t('start_tour'), icon: 'info', act: 'tour' });
  return items;
}
// core.js:1575-1583 openUserMenu — dark = the theme now on (the item offers the other one)
function krUserMenuItems(dark = false) {
  return [
    { label: t('nav_settings'), icon: 'settings', act: 'settings' },
    { label: t(dark ? 'light_mode' : 'dark_mode'), icon: dark ? 'sun' : 'moon', act: 'theme' },
    { sep: true },
    { label: t('logout'), icon: 'log-out', danger: true, act: 'logout' },
  ];
}

// core.js:1486-1498 uiOverlay('modal', …) as ui.modal (core.js:1511) builds it: div.overlay > div.modal.<size>
// (role="dialog" aria-modal) > .modal-head (h2.modal-title + close button [data-close]) + .modal-body (body) +
// .modal-foot (only when footer is truthy). The app's random id 'dlg-' + uid() is `${p}-dlg` here.
// cls = extra classes on .modal, added the way callers do it (classList.add, e.g. detail-views.js:707 'dd-modal').
// headExtra = markup put between the title and the close button (the app never does this; '' keeps it identical).
function krModalWrap(o = {}) {
  const p = o.p || 'kr', id = `${p}-dlg`;
  const size = o.size === undefined ? 'md' : o.size;
  let cls = `modal ${size}`;
  if (o.cls) cls = [...new Set(`${cls} ${o.cls}`.split(/\s+/).filter(Boolean))].join(' ');   // DOMTokenList.add serialises the set
  return `<div class="overlay"><div class="${esc(cls)}" role="dialog" aria-modal="true" aria-labelledby="${id}"><div class="modal-head"><h2 class="modal-title" id="${id}">${esc(o.title)}</h2>${o.headExtra || ''}<button class="iconbtn" data-close aria-label="${esc(t('btn_close'))}">${icon('x')}</button></div><div class="modal-body">${o.body == null ? '' : o.body}</div>${o.footer ? `<div class="modal-foot">${o.footer}</div>` : ''}</div></div>`;
}

// core.js:1486-1498 uiOverlay('drawer', …) as ui.drawer (core.js:1515) builds it: div.overlay.drawer-wrap > aside.drawer
// (role="dialog" aria-modal, the width as style="width:min(<width>px,100%)" when given) > .modal-head (h2.modal-title +
// close button [data-close]) + .modal-body (style flex:1 1 auto) + .modal-foot (style border-radius:0, only when footer is
// truthy). The app's random id 'dlg-' + uid() is `${p}-dlg` here. cls = extra classes on .drawer, as callers add them
// (detail-views.js:1201 'tk-drawer').
function krDrawerWrap(o = {}) {
  const p = o.p || 'kr', id = `${p}-dlg`, width = o.width;
  const cls = o.cls ? [...new Set(`drawer ${o.cls}`.split(/\s+/).filter(Boolean))].join(' ') : 'drawer';
  return `<div class="overlay drawer-wrap"><aside class="${esc(cls)}" role="dialog" aria-modal="true" aria-labelledby="${id}" ${width ? `style="width:min(${width}px,100%)"` : ''}><div class="modal-head"><h2 class="modal-title" id="${id}">${esc(o.title)}</h2><button class="iconbtn" data-close aria-label="${esc(t('btn_close'))}">${icon('x')}</button></div><div class="modal-body" style="flex:1 1 auto">${o.body == null ? '' : o.body}</div>${o.footer ? `<div class="modal-foot" style="border-radius:0">${o.footer}</div>` : ''}</aside></div>`;
}

// core.js:1516-1522 ui.confirm({ title, message, confirmLabel, cancelLabel, danger }): an sm modal, the message in
// p.sub, the footer Cancel [data-no] then Confirm [data-yes] (btn-danger when danger, else btn-primary).
function krConfirm(o = {}) {
  const confirmLabel = o.confirmLabel === undefined ? t('core_confirm') : o.confirmLabel;
  const cancelLabel = o.cancelLabel === undefined ? t('btn_cancel') : o.cancelLabel;
  return krModalWrap({ p: o.p, title: o.title, size: 'sm', body: `<p class="sub">${esc(o.message)}</p>`,
    footer: `<button class="btn btn-secondary" data-no>${esc(cancelLabel)}</button><button class="btn ${o.danger ? 'btn-danger' : 'btn-primary'}" data-yes>${esc(confirmLabel)}</button>` });
}

// core.js:1640-1643 showShortcuts(): what the help menu's "Tastenkürzel" item opens.
function krShortcuts(o = {}) {
  const row = (k, txt) => `<div class="row-between" style="padding:8px 0;border-bottom:1px solid var(--divider)"><span>${esc(txt)}</span><span class="kbd">${esc(k)}</span></div>`;
  return krModalWrap({ p: o.p, title: t('kbd_shortcuts'), size: 'sm', body: row('Ctrl K', t('sc_search')) + row('/', t('sc_search')) + row('Esc', t('sc_close')) + row('↑ ↓', t('sc_move')), footer: `<button class="btn btn-secondary" data-close>${esc(t('btn_close'))}</button>` });
}


/* ════ deals ════ */
/* kr-deals.js — the Deals page (board view) as pure renderers for the landing-page replica.
   Ported from the app's public/js/deals.js and public/index.html:403-433 (branch v2.3.2). Each template is
   the app's own, byte for byte, except: inline on*="" handlers and draggable="true" are gone (the ones whose
   element had no other hook became data-kr="…"), every id is "<p>-<id>", the four ID-styled containers carry a
   class hook (kr-deals-board / kr-deals-summary / kr-deals-list-view / kr-deals-list-foot, rules in
   kr-deals.css), and the selected pipeline <option> carries `selected` (the app sets select.value instead).
   The app's globals (pipelines, deals, members, currentUser, dealFields, currentPipelineId, dealsUI) arrive in
   one options object `o`; krDealsState() fills the defaults. Needs kr-core.js loaded first.
   Proof: kr-deals.check.js renders the same data through the app's own functions and asserts equality. */

/* ---------- state (the app's globals, as one object) ---------- */
// o → the app's state. pipelineId is resolved the way populatePipelineSelect() does it in board mode
// (deals.js:152-162): no id → the first pipeline; an id that matches no pipeline → null ("no pipeline selected").
// The app resolves once per load, so an already-resolved state (krState: true) is returned as it is.
function krDealsState(o = {}) {
  if (o.krState) return o;
  const pipelines = o.pipelines || [];
  let pipelineId = o.pipelineId ?? null;
  if (!pipelineId && pipelines.length) pipelineId = pipelines[0].id;
  if (pipelineId && !pipelines.find(p => p.id === pipelineId)) pipelineId = null;
  return {
    krState: true,
    p: o.p || 'kr',
    pipelines, pipelineId,
    deals: o.deals || [],                 // GET /api/deals?pipeline_id=<pipelineId>: that pipeline only, created_at DESC
    members: o.members || [],             // the owner chip's label (deals.js:336)
    currentUser: o.currentUser || null,   // the owner chip menu's "(you)" (deals.js:351)
    dealFields: o.dealFields || [],       // custom dropdown fields → extra chips (deals.js:326)
    summary: o.summary !== false,         // dealsUI.summary, default on (localStorage.dealsSummary !== '0')
    q: o.q || '',
    owner: o.owner ?? null,               // null = all, '' = unassigned, else a user id
    urgency: o.urgency ?? null,           // null = all, else 1–4 ("or higher")
    stage: o.stage ?? null,               // null = all, '' = no stage, else a stage id
    cf: o.cf || {},                       // { field_key: option }
    busy: !!o.busy,                       // a stage PATCH in flight → #deals-board[aria-busy="true"]
  };
}

// deals.js:89
function krDealsSum(list) { return list.reduce((s, d) => s + (Number(d.value) || 0), 0); }
// deals.js:96
function krDealsPipeline(s) { return s.pipelines.find(p => p.id === s.pipelineId) || null; }
// deals.js:97 (takes the pipelines list instead of the global)
function krDealStagesOf(pipelines, d) { return (pipelines || []).find(p => p.id === d.pipeline_id)?.stages || []; }
// deals.js:101-105
function krDealsSummaryStages(s) {
  const p = krDealsPipeline(s);
  if (p) return (p.stages || []).map(st => ({ ...st, label: st.name }));
  return s.pipelines.flatMap(pl => (pl.stages || []).map(st => ({ ...st, label: `${pl.name} · ${st.name}` })));
}

// deals.js:108-118 — the deals the filters let through. Order is KEPT: the board never sorts; a column lists its
// cards in the order of `deals` (the API's ORDER BY created_at DESC), so a moved card lands at its created_at
// position in the new column, not where it was dropped.
function krVisibleDeals(o) {
  const s = krDealsState(o);
  const q = String(s.q || '').trim().toLowerCase();
  return s.deals.filter(d => {
    if (q && !`${d.title || ''} ${d.contact_name || ''} ${d.contact_company || ''}`.toLowerCase().includes(q)) return false;
    if (s.owner != null && (d.assigned_to ?? '') !== s.owner) return false;
    if (s.urgency != null && (parseInt(d.urgency, 10) || 0) < s.urgency) return false;
    if (s.stage != null && (d.stage_id ?? '') !== s.stage) return false;
    for (const [k, v] of Object.entries(s.cf || {})) { if (v != null && v !== '' && String(d.custom_data?.[k] ?? '') !== v) return false; }
    return true;
  });
}
// deals.js:120-124
function krDealsKpis(list) {
  const valued = list.filter(d => d.value != null && d.value !== '');
  const value = krDealsSum(list);
  return { value, count: list.length, avg: valued.length ? Math.round(value / valued.length) : 0, urgent: list.filter(d => (parseInt(d.urgency, 10) || 0) >= 3).length };
}
// routes/deals.js:68-92 (GET /api/deals[?pipeline_id]) — WHERE pipeline_id = …, ORDER BY d.created_at DESC.
// Use it to build o.deals from sample data; ties keep their input order.
function krDealsFromApi(all, pipelineId) {
  return (all || []).filter(d => !pipelineId || d.pipeline_id === pipelineId)
    .slice().sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
}

/* ---------- state changes the app makes (pure: they return new values) ---------- */
// deals.js:437-440 applyStage — the fields a stage move writes onto the deal.
function krDealStagePatch(o, deal, stageId) {
  const stage = krDealStagesOf(o.pipelines, deal).find(st => st.id === stageId);
  return { stage_id: stageId, stage_name: stage?.name || null, stage_color: stage?.color || null };
}
// The app mutates the deal in place (deals.js:439, 461, 465, 475), so it keeps its array index; this does the same
// without mutation: a new array, same order, the one deal replaced by { ...deal, ...patch }.
function krPatchDeal(deals, id, patch) { return deals.map(d => (d.id === id ? { ...d, ...patch } : d)); }

/* ---------- header ---------- */
// deals.js:193 — the sub line's TEXT (the app sets textContent; krDealsPage escapes it).
function krDealsSubText(o) {
  const s = krDealsState(o), cp = krDealsPipeline(s);
  return cp ? tf('deals_in_pipeline', { n: s.deals.length, p: cp.name }) : tf('deals_all_pipelines', { n: s.deals.length });
}
// deals.js:155-156 (board mode: no "All pipelines" option) + `selected` standing in for sel.value (deals.js:161).
function krDealsPipelineOptions(o) {
  const s = krDealsState(o);
  return s.pipelines.map(p => `<option value="${p.id}"${p.id === s.pipelineId ? ' selected' : ''}>${esc(p.name)}</option>`).join('');
}

// index.html:403-433, translated the way applyTranslations() (core.js:1069) fills data-i18n / data-i18n-aria,
// with the parts deals.js fills (sub, select, summary, toolbar, board) and setDealView('kanban') applied.
function krDealsPage(o) {
  const s = krDealsState(o), p = s.p;
  return `<section id="${p}-page-deals" class="page active">
  <div class="page-header">
    <div>
      <h1 class="page-title" data-i18n="nav_deals">${esc(t('nav_deals'))}</h1>
      <p class="page-sub" id="${p}-deals-page-sub">${esc(krDealsSubText(s))}</p>
    </div>
    <div class="page-actions">
      <select id="${p}-deals-pipeline-select" class="btn btn-secondary deals-pipeline-select" data-kr="pipeline">${krDealsPipelineOptions(s)}</select>
      <div class="seg" role="group" aria-label="${esc(t('tk_view'))}" data-i18n-aria="tk_view">
        <button id="${p}-deal-view-kanban" aria-pressed="true" data-kr="view-board" type="button"><svg class="ic ic-sm" aria-hidden="true"><use href="#i-kanban"/></svg><span data-i18n="view_board">${esc(t('view_board'))}</span></button>
        <button id="${p}-deal-view-list" aria-pressed="false" data-kr="view-list" type="button"><svg class="ic ic-sm" aria-hidden="true"><use href="#i-list"/></svg><span data-i18n="view_list">${esc(t('view_list'))}</span></button>
      </div>
      <button class="btn btn-secondary btn-icon" data-kr="more" type="button" aria-label="${esc(t('html_more_actions'))}" data-i18n-aria="html_more_actions" aria-haspopup="menu"><svg class="ic" aria-hidden="true"><use href="#i-ellipsis"/></svg></button>
      <button class="btn btn-primary" data-kr="add-deal"><svg class="ic" aria-hidden="true"><use href="#i-plus"/></svg><span data-i18n="add_deal">${esc(t('add_deal'))}</span></button>
    </div>
  </div>
  <!-- Summary (KPIs + value by stage), toolbar, then the board or the list. All filled by deals.js. -->
  <section id="${p}-deals-summary" class="card summary${s.summary ? '' : ' hidden'} kr-deals-summary" aria-label="${esc(t('html_pipeline_summary'))}" data-i18n-aria="html_pipeline_summary">${krDealsSummary(s)}</section>
  <div id="${p}-deals-toolbar" class="toolbar">${krDealsToolbar(s)}</div>
  <div id="${p}-deals-board" class="board kr-deals-board"${s.busy ? ' aria-busy="true"' : ''}>${krDealsBoard(s)}</div>
  <div id="${p}-deals-list-view" class="deals-list hidden kr-deals-list-view">
    <div id="${p}-deals-bulkbar"></div>
    <div class="table-wrap">
      <table class="table" id="${p}-deals-table">
        <thead id="${p}-deals-thead"></thead>
        <tbody id="${p}-deals-tbody"></tbody>
      </table>
    </div>
    <div id="${p}-deals-list-foot" class="table-foot kr-deals-list-foot"></div>
  </div>
</section>`;
}

/* ---------- summary ---------- */
// deals.js:279-295 — the innerHTML of #deals-summary; '' when the summary is off (the container then also
// carries class "hidden"). Counts ALL of o.deals: search and chips do not change it.
function krDealsSummary(o) {
  const s = krDealsState(o);
  if (!s.summary) return '';
  const all = s.deals, k = krDealsKpis(all), total = k.value || 1, stages = krDealsSummaryStages(s), cp = krDealsPipeline(s);
  const kpi = (label, value, foot) => `<div class="kpi"><div class="kpi-label">${esc(label)}</div><div class="kpi-value">${value}</div><div class="kpi-foot">${esc(foot)}</div></div>`;
  return `<div class="kpis">
      ${kpi(t('kpi_pipeline_value'), fmtEURShort(k.value), cp ? cp.name : t('opt_all_pipelines'))}
      ${kpi(t('kpi_deals'), String(k.count), t('kpi_deals_foot'))}
      ${kpi(t('kpi_avg_deal'), fmtEURShort(k.avg), t('kpi_avg_foot'))}
      ${kpi(t('kpi_urgent'), String(k.urgent), t('kpi_urgent_foot'))}
    </div>` + (stages.length ? `<div class="strip">
      <div class="stack" role="img" aria-label="${esc(t('strip_label'))}">${stages.map(st => { const v = krDealsSum(all.filter(d => d.stage_id === st.id)); return `<button type="button" style="flex:${Math.max(v, total * .015)};background:${esc(st.color)}" data-jump="${st.id}" title="${esc(st.label)}: ${fmtEURShort(v)}" aria-label="${esc(st.label)}"></button>`; }).join('')}</div>
      <div class="stack-legend">${stages.map(st => { const a = all.filter(d => d.stage_id === st.id); return `<button type="button" data-jump="${st.id}"><div class="nm"><i style="background:${esc(st.color)}"></i>${esc(st.label)}</div><div class="v">${fmtEURShort(krDealsSum(a))}</div><div class="c">${esc(tf('n_deals', { n: a.length }))}</div></button>`; }).join('')}</div>
    </div>` : '');
}

/* ---------- toolbar ---------- */
// deals.js:313-322 — the innerHTML of #deals-toolbar in board mode (the Columns button is list-only).
function krDealsToolbar(o) {
  const s = krDealsState(o), p = s.p;
  const any = krDealsFilterActive(s);
  return `<div class="input-group" style="width:260px">${icon('search')}<input class="input" id="${p}-deals-q" type="search" placeholder="${esc(t('search_deals'))}" value="${esc(s.q)}" aria-label="${esc(t('search_deals'))}" data-kr="search"></div>
    ${krDealsChip(s, 'owner')}${krDealsChip(s, 'urgency')}${krDealsChip(s, 'stage')}${krDealFilterFields(s).map(f => krDealsChip(s, 'cf:' + f.field_key, f.name)).join('')}
    ${any ? `<button class="btn btn-ghost btn-sm" type="button" data-kr="clear-filters">${esc(t('clear_filters'))}</button>` : ''}<span class="grow"></span>
    ${'' /* deals.js:320: the "Spalten" (columns) button, list mode only */}
    <button class="btn btn-secondary btn-sm" type="button" data-kr="toggle-summary" aria-pressed="${s.summary}">${icon('bar-chart')}${esc(t(s.summary ? 'hide_summary' : 'show_summary'))}</button>`;
}
// deals.js:326
function krDealFilterFields(o) { return krDealsState(o).dealFields.filter(f => f.type === 'dropdown' && f.options?.length); }
// deals.js:327-330
function krDealsFilterActive(o) {
  const s = krDealsState(o);
  return !!(s.q || s.owner != null || s.urgency != null || s.stage != null
    || Object.values(s.cf || {}).some(v => v != null && v !== ''));
}
// deals.js:331-341
function krDealsChip(o, key, label) {
  const s = krDealsState(o);
  const cf = key.startsWith('cf:'), v = cf ? s.cf?.[key.slice(3)] : s[key];
  const on = v != null && v !== '' || (!cf && v === '');
  let txt = '';
  if (on) txt = cf ? String(v)
    : v === '' ? t('detail_unassigned')
    : key === 'owner' ? (s.members.find(m => m.id === v)?.name || '')
    : key === 'urgency' ? `${urgencyLabel(urgencyMeta(v))} ${t('or_higher')}`
    : (krDealsSummaryStages(s).find(st => st.id === v)?.label || '');
  return `<button class="chip ${on ? 'on' : ''}" type="button" data-chip="${esc(key)}" aria-haspopup="menu">${esc(label || t('chip_' + key))}${on ? ': ' + esc(txt) : ''}${icon('chevron-down', 'ic-sm')}</button>`;
}

/* ---------- board ---------- */
// deals.js:373-396 — the innerHTML of #deals-board: the columns, or one of the two empty states.
function krDealsBoard(o) {
  const s = krDealsState(o);
  if (!s.pipelines.length) {
    return `<div class="empty" style="flex:1">${icon('deals')}<b>${esc(t('no_pipelines'))}</b></div>`;
  }
  const pipeline = krDealsPipeline(s);
  if (!pipeline) {
    return `<div class="empty" style="flex:1">${icon('kanban')}<b>${esc(t('no_pipeline_selected'))}</b></div>`;
  }
  const list = krVisibleDeals(s), total = krDealsSum(s.deals) || 1;
  return (pipeline.stages || []).map(stage => {
    const items = list.filter(d => d.stage_id === stage.id), v = krDealsSum(items);
    return `<section class="col-board" data-stage="${stage.id}" aria-label="${esc(stage.name)}">
      <div class="col-head"><i style="width:9px;height:9px;border-radius:50%;background:${esc(stage.color)}"></i><span class="nm">${esc(stage.name)}</span><span class="cnt">${items.length}</span>
        <button class="iconbtn" type="button" style="margin-left:auto;width:28px;height:28px" data-add="${stage.id}" aria-label="${esc(t('add_deal'))}: ${esc(stage.name)}">${icon('plus')}</button></div>
      <div class="col-sum">${fmtEURShort(v)}</div><div class="col-bar"><i style="width:${Math.round(v / total * 100)}%;background:${esc(stage.color)}"></i></div>
      <div class="col-cards">${items.length ? items.map(krDealCard).join('') : `<div class="muted" style="text-align:center;padding:24px 8px;font-size:var(--fs-sm)">${esc(t('no_deals'))}</div>`}</div>
    </section>`;
  }).join('');
}

// deals.js:402-416 — one card. d = one row of GET /api/deals.
function krDealCard(d) {
  const u = parseInt(d.urgency, 10) || 0, m = urgencyMeta(u);
  const who = d.contact_name ? esc(d.contact_name) + (d.contact_company ? ', ' + esc(d.contact_company) : '') : esc(t('no_contact'));
  return `<div class="dcard" tabindex="0" role="button" data-id="${d.id}" aria-label="${esc(d.title)}, ${fmtEUR(d.value)}">
    ${u > 0 ? `<span class="urg urg-${u}" title="${esc(urgencyLabel(m))}"></span>` : ''}
    <button class="iconbtn kebab" type="button" data-kr="kebab" aria-label="${esc(t('open_deal'))}: ${esc(d.title)}">${icon('ellipsis')}</button>
    <div class="dcard-title" style="padding-right:22px">${esc(d.title)}</div>
    <div class="dcard-meta truncate">${who}</div>
    <div class="dcard-foot"><span class="dcard-value">${d.value != null ? fmtEUR(d.value) : '<span class="muted">—</span>'}</span>${urgencyBadge(u)}<span style="margin-left:auto">${avatar(d.assigned_to_name, 'sm')}</span></div>
    <div class="dcard-sub"><span class="row" style="gap:5px" title="${esc(t('created_lbl'))}">${icon('calendar')}${fmtDateShort(d.created_at)}</span><span class="row" style="gap:5px" title="${esc(t('updated_lbl'))}">${icon('clock')}${agoDays(d.updated_at || d.created_at)}</span></div>
  </div>`;
}

/* ---------- menus: the item arrays the app hands to ui.menu (core.js:1471) ----------
   Item shape = ui.menu's: { label, icon?, hint?, checked?, danger? } | { sep: true } | { heading }.
   onSelect is replaced by data: act (what to do) + id / stageId / key / value. ui.menu numbers the
   buttons data-i = index in this array (headings and separators count). */

// deals.js:423-435 openDealKebab — opened with { align: 'right' } at the card's ⋯.
// o = { deal, stages } (stages = the deal's pipeline's stages; or pass { deal, pipelines }).
function krDealKebabItems(o) {
  const d = o.deal;
  if (!d) return [];
  const id = d.id, stages = o.stages || krDealStagesOf(o.pipelines, d);
  return [
    { label: t('open_deal'), icon: 'external', act: 'open', id },
    ...(stages.length ? [{ heading: t('move_to_stage') }, ...stages.map(st => ({ label: st.name, checked: st.id === d.stage_id, act: 'move', id, stageId: st.id }))] : []),
    { sep: true },
    { label: t('set_urgency'), icon: 'flag', act: 'urgency', id },
    { sep: true },
    { label: t('delete_deal'), icon: 'trash', danger: true, act: 'delete', id },
  ];
}
// deals.js:432 → core.js:1481 ui.select — the menu "Dringlichkeit setzen" opens at the SAME kebab
// (default align = left edge on the kebab's left edge). The current level is checked.
function krDealUrgencyItems(deal) {
  const cur = parseInt(deal.urgency, 10) || 0;
  return DEAL_URGENCY.map(u => ({ label: urgencyLabel(u), checked: u.value === cur, act: 'set-urgency', id: deal.id, value: u.value }));
}
// deals.js:342-361 openDealsChip → ui.select under the chip (left-aligned). key = 'owner' | 'urgency' | 'stage' | 'cf:<field_key>'.
// Picking an item sets that filter to item.value (null = "Alle") and re-renders everything.
function krDealsChipItems(o, key) {
  const s = krDealsState(o);
  const unassigned = { value: '', label: t('detail_unassigned') };
  let opts, cur;
  if (key.startsWith('cf:')) {
    const f = s.dealFields.find(x => x.field_key === key.slice(3)); if (!f) return [];
    opts = (f.options || []).map(op => ({ value: op, label: op }));
    cur = s.cf?.[f.field_key] ?? null;
  } else if (key === 'owner') {
    opts = [unassigned, ...s.members.map(m => ({ value: m.id, label: m.name + (m.id === s.currentUser?.id ? ' (you)' : '') }))];
    cur = s.owner ?? null;
  } else if (key === 'urgency') {
    opts = [1, 2, 3, 4].map(i => ({ value: i, label: `${urgencyLabel(urgencyMeta(i))} ${t('or_higher')}` }));
    cur = s.urgency ?? null;
  } else {
    opts = [unassigned, ...krDealsSummaryStages(s).map(st => ({ value: st.id, label: st.label }))];
    cur = s.stage ?? null;
  }
  return [{ value: null, label: t('filter_all') }, ...opts].map(op => ({ label: op.label, checked: op.value === cur, act: 'filter', key, value: op.value }));
}
// deals.js:587-593 openDealsMoreMenu — the header ⋯, { align: 'right' }.
function krDealsMoreItems() {
  return [
    { label: t('export_csv'), icon: 'download', act: 'export-csv' },
    { sep: true },
    { label: t('manage_pipelines'), icon: 'settings', act: 'manage-pipelines' },
  ];
}

/* ---------- drag autoscroll (deals.js:629-638) ---------- */
// While a card is dragged, a frame loop scrolls the board sideways (and the .col-cards under the pointer up/down)
// by this many px per frame when the pointer is within `edge` px of an edge. Pure; the loop is the page's.
const KR_DEAL_AUTOSCROLL = { edge: 72, max: 24 };
function krDealEdgeScrollDelta(pos, start, end, { edge, max } = KR_DEAL_AUTOSCROLL) {
  if (!(end - start > edge * 2)) return 0;   // a span too narrow for two edge zones never scrolls
  if (pos < start + edge) return -Math.ceil(Math.min(1, (start + edge - pos) / edge) * max);
  if (pos > end - edge)   return  Math.ceil(Math.min(1, (pos - (end - edge)) / edge) * max);
  return 0;
}


/* ════ forms ════ */
/* kr-forms.js — three CRM screens as pure renderers for the landing-page replica (Part 49):
     1. the deal dialog "Neuer Deal" (and its edit mode "Deal bearbeiten") — public/js/detail-views.js:428-492 openDealForm
     2. the Deals list view ("Liste") — public/js/deals.js:152-189, 200-273, 303-322, 484-582 + public/index.html:403-433
     3. the contact dialog "Kontakt hinzufügen" (and its edit mode) — public/index.html:1532-1556 + public/js/modals.js:26-104
   Branch v2.3.2, read 2026-10-27. Each template is the app's own, byte for byte, changed only by the rules in
   kr-forms.md §7: inline handlers → data-kr="…" in place, ids → `${p}-<id>`, the random form/dialog ids → `${p}-df` /
   `${p}-dlg`, and DOM state written as attributes (a select's current option carries `selected`, an input's current
   value its `value`, as if the app's template had been given that value).
   Load AFTER kr-core.js, kr-shell.js (krModalWrap = ui.modal) and kr-deals.js (the list reuses its state, summary,
   chips, visible-deal filter and kebab menu). Every top-level name starts with krFm / KR_FM_.
   Proof: kr-forms.check.js runs the app's own code over index.html's real markup and asserts equality. */

/* ════════════════════════════════════════════════════════════════════════════════════════════════
   shared
   ════════════════════════════════════════════════════════════════════════════════════════════════ */

// Text the app writes with textContent, escaped the way a browser serialises a text node: & < > and U+00A0
// (quotes stay). Used for the dictionary words applyTranslations() writes, the dialog titles and the error lines.
function krFmText(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/\u00A0/g, '&nbsp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// The browser's value sanitisation for the input types these forms draw (HTML "value sanitization algorithm"):
// what .value reports for what was typed or set. number/date: anything invalid reads as ''.
function krFmValidDate(v) {
  const m = /^(\d{4,})-(\d{2})-(\d{2})$/.exec(v);
  if (!m) return false;
  const y = +m[1], mo = +m[2], d = +m[3];
  if (y < 1 || mo < 1 || mo > 12 || d < 1) return false;
  const leap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
  return d <= [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][mo - 1];
}
function krFmSanitize(type, v) {
  v = String(v ?? '');
  if (type === 'number') return /^-?(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(v) ? v : '';
  if (type === 'date') return krFmValidDate(v) ? v : '';
  if (type === 'email' || type === 'url') return v.replace(/[\r\n]/g, '').replace(/^[\t\n\f\r ]+|[\t\n\f\r ]+$/g, '');
  if (type === 'text' || type === 'tel' || type === 'search') return v.replace(/[\r\n]/g, '');
  return v;
}
// The value a <select> reports: the option whose value equals cur, else the first option ('' when it has none).
function krFmSelValue(values, cur) {
  const c = String(cur ?? ''), vals = values.map(String);
  return vals.includes(c) ? c : (vals.length ? vals[0] : '');
}

/* ════════════════════════════════════════════════════════════════════════════════════════════════
   1. THE DEAL DIALOG — detail-views.js:428-492 openDealForm(opts)
      Opened by: "Deal hinzufügen" (openDealModal() → no opts), the column "+" (deals.js:418 addDealInStage →
      { pipelineId: currentPipelineId, stageId }), the top bar "Neu › Deal" (core.js:1562 → openDealModal()),
      the contact record "Deal hinzufügen" ({ contactId }), and the deal record ⋯ "Deal bearbeiten" / "Alles
      bearbeiten" ({ deal }) — the same form, prefilled, titled "Deal bearbeiten".
   ════════════════════════════════════════════════════════════════════════════════════════════════ */

// detail-views.js:443 typeMap (custom field type → <input type>)
const KR_FM_CF_TYPES = { text: 'text', email: 'email', phone: 'tel', number: 'number', date: 'date', url: 'url' };

// detail-views.js:68 dvSupplierWord — the workspace's supplier word, singular (trailing s cut), else "Lieferant"
function krFmSupplierWord(o) {
  const w = o && o.workspace && o.workspace.supplier_name;
  return w ? w.replace(/s$/i, '') : t('dv_supplier_one');
}

// detail-views.js:438 opt — note the space before the empty `selected` slot: an unselected option is `<option value="2" >`.
function krFmOpt(v, label, cur) { return `<option value="${esc(v)}" ${String(cur ?? '') === String(v) ? 'selected' : ''}>${esc(label)}</option>`; }

// detail-views.js:429-436 — the state openDealForm builds from its globals and opts. o (see kr-forms.md §2.1):
//   p, pipelines, currentPipelineId, pipelineId, stageId, contactId, deal (edit mode), contacts, suppliers, members,
//   currentUser, dealFields, workspace, values (the controls the user changed), err, locked, submitting, dealsPageActive.
function krFmDealState(o = {}) {
  if (o.krFmDeal) return o;
  const pipelines = o.pipelines || [];
  const contacts = o.contacts || [];
  const editing = o.deal || null;
  const init = editing ? { ...editing } : { pipeline_id: o.pipelineId || o.currentPipelineId || pipelines[0]?.id || null, stage_id: o.stageId || null, title: '', contact_id: o.contactId || null, supplier_id: null, value: '', urgency: 0, assigned_to: o.currentUser?.id || null, custom_data: {} };
  if (!pipelines.find(p => p.id === init.pipeline_id)) init.pipeline_id = pipelines[0]?.id || null;
  const stagesFor = pid => pipelines.find(p => p.id === pid)?.stages || [];
  if (!init.stage_id || !stagesFor(init.pipeline_id).some(s => s.id === init.stage_id)) init.stage_id = stagesFor(init.pipeline_id)[0]?.id || null;
  if (!editing && o.contactId) { const c = contacts.find(x => x.id === o.contactId); if (c) { init.title = c.name; if (c.assigned_to) init.assigned_to = c.assigned_to; } }
  return {
    krFmDeal: true, p: o.p || 'kr', pipelines, contacts, suppliers: o.suppliers || [], members: o.members || [],
    currentUser: o.currentUser || null, dealFields: o.dealFields || [], workspace: o.workspace || null,
    currentPipelineId: o.currentPipelineId ?? null, editing, init,
    values: o.values || {},             // { title, value, contact, supplier, pipeline, stage, urgency, owner, cf: { key: v } } as typed / picked
    err: o.err || {},                   // { title?: text, value?: text } — the error lines setErr() wrote
    locked: !!o.locked,                 // core.js:1381 the 1 s .is-save-locked on the submit button after a click
    submitting: !!o.submitting,         // core.js:1361 the 10 s submit guard: the submit button is disabled
    dealsPageActive: o.dealsPageActive !== false,   // #page-deals is the active page (the board reloads after a save)
  };
}
// detail-views.js:434 stagesFor
function krFmDealStagesFor(o, pid) { return (o.pipelines || []).find(p => p.id === pid)?.stages || []; }

// What each control reports (its .value), from init + the user's changes. attr = what the value attribute shows.
function krFmDealControls(o) {
  const s = krFmDealState(o), init = s.init, v = s.values, cfv = v.cf || {};
  const has = k => Object.prototype.hasOwnProperty.call(v, k);
  const titleAttr = has('title') ? krFmSanitize('text', v.title) : (init.title == null ? '' : String(init.title));
  const valueTpl = init.value == null || init.value === '' ? '' : String(init.value);
  const valueAttr = has('value') ? krFmSanitize('number', v.value) : valueTpl;
  const pipeline = krFmSelValue(s.pipelines.map(p => p.id), has('pipeline') ? v.pipeline : init.pipeline_id);
  const st = krFmDealStagesFor(s, parseInt(pipeline, 10));
  const stageTpl = st.some(x => x.id === Number(init.stage_id)) ? init.stage_id : st[0]?.id;   // fillStages (detail-views.js:463)
  const stageCur = has('stage') ? v.stage : stageTpl;
  const cf = {}, cfAttr = {};
  for (const f of s.dealFields) {
    const tpl = init.custom_data?.[f.field_key] ?? '';
    const k = f.field_key, typed = Object.prototype.hasOwnProperty.call(cfv, k);
    if (f.type === 'dropdown') { cfAttr[k] = typed ? cfv[k] : tpl; cf[k] = krFmSelValue(['', ...(f.options || [])], cfAttr[k]); }
    else { const ty = KR_FM_CF_TYPES[f.type] || 'text'; cfAttr[k] = typed ? krFmSanitize(ty, cfv[k]) : String(tpl); cf[k] = typed ? cfAttr[k] : krFmSanitize(ty, tpl); }
  }
  return {
    titleAttr, title: has('title') ? titleAttr : krFmSanitize('text', titleAttr), valueAttr, value: has('value') ? valueAttr : krFmSanitize('number', valueTpl),
    contactCur: has('contact') ? v.contact : init.contact_id, contact: krFmSelValue(['', ...s.contacts.map(c => c.id)], has('contact') ? v.contact : init.contact_id),
    supplierCur: has('supplier') ? v.supplier : init.supplier_id, supplier: krFmSelValue(['', ...s.suppliers.map(c => c.id)], has('supplier') ? v.supplier : init.supplier_id),
    pipelineCur: has('pipeline') ? v.pipeline : init.pipeline_id, pipeline,
    stages: st, stageCur, stage: krFmSelValue(st.map(x => x.id), stageCur),
    urgencyCur: has('urgency') ? v.urgency : init.urgency, urgency: krFmSelValue(DEAL_URGENCY.map(u => u.value), has('urgency') ? v.urgency : init.urgency),
    ownerCur: has('owner') ? v.owner : init.assigned_to, owner: krFmSelValue(['', ...s.members.map(m => m.id)], has('owner') ? v.owner : init.assigned_to),
    cf, cfAttr,
    dirty: { contact: has('contact'), supplier: has('supplier'), owner: has('owner'), cf: Object.fromEntries(s.dealFields.map(f => [f.field_key, Object.prototype.hasOwnProperty.call(cfv, f.field_key)])) },
  };
}
// a select the user changed holds `selected` on the option it reports — also on the template's hard-coded '' option
function krFmEmptyOpt(dirty, value) { return dirty && value === '' ? ' selected' : ''; }

// detail-views.js:463 fillStages — the stage <select>'s options for the pipeline the form shows. The app re-runs it
// when the pipeline <select> changes (after setting the stage to ''): drop values.stage when values.pipeline changes.
function krFmDealStageOptions(o) {
  const V = krFmDealControls(o);
  return V.stages.map(s => krFmOpt(s.id, s.name, V.stageCur)).join('');
}

// detail-views.js:439 fld + 466 setErr — one field; err = the text setErr wrote ('' none), invalid = aria-invalid on the control
function krFmDealField(id, label, control, { req, help } = {}, errText = '') {
  return `<div class="field"><label class="label" for="${id}">${label}${req ? ' <span class="req" aria-hidden="true">*</span>' : ''}</label>${control}${help ? `<div class="help">${help}</div>` : ''}<div class="error-text" id="${id}-err" role="alert">${krFmText(errText)}</div></div>`;
}

// detail-views.js:440-445 customField
function krFmDealCustomField(s, V, f) {
  const fid = `${s.p}-df`, id = `${fid}-cf-${f.field_key}`, v = V.cfAttr[f.field_key];
  if (f.type === 'dropdown') return krFmDealField(id, esc(f.name), `<select class="select" id="${id}" data-cf="${esc(f.field_key)}"><option value=""${krFmEmptyOpt(V.dirty.cf[f.field_key], V.cf[f.field_key])}>${esc(t('not_set'))}</option>${(f.options || []).map(op => krFmOpt(op, op, v)).join('')}</select>`);
  return krFmDealField(id, esc(f.name), `<input class="input" id="${id}" data-cf="${esc(f.field_key)}" type="${KR_FM_CF_TYPES[f.type] || 'text'}" value="${esc(v)}" autocomplete="off">`);
}

// detail-views.js:446-461 — the <form> the dialog body holds (createElement('form'): class, id, noValidate set in that order).
function krFmDealFormBody(o) {
  const s = krFmDealState(o), V = krFmDealControls(s), fid = `${s.p}-df`;
  const fld = (id, label, control, opts) => krFmDealField(id, label, control, opts, id === `${fid}-title` ? s.err.title : id === `${fid}-value` ? s.err.value : '');
  const inv = k => (s.err[k] ? ' aria-invalid="true"' : '');
  const opt = krFmOpt;
  return `<form class="dd-form" id="${fid}" novalidate>
    ${fld(`${fid}-title`, esc(t('lbl_deal_title')), `<input class="input" id="${fid}-title" name="title" maxlength="140" autocomplete="off" placeholder="${esc(t('dv_deal_title_ph'))}" value="${esc(V.titleAttr)}" autofocus aria-required="true"${inv('title')}>`, { req: true })}
    <div class="field-row">
      ${fld(`${fid}-contact`, esc(t('lbl_contact')), `<select class="select" id="${fid}-contact" name="contact"><option value=""${krFmEmptyOpt(V.dirty.contact, V.contact)}>${esc(t('no_contact'))}</option>${s.contacts.map(c => opt(c.id, c.company ? `${c.name}, ${c.company}` : c.name, V.contactCur)).join('')}</select>`, { help: esc(t('dv_contact_help')) })}
      ${fld(`${fid}-supplier`, esc(krFmSupplierWord(s)), `<select class="select" id="${fid}-supplier" name="supplier"><option value=""${krFmEmptyOpt(V.dirty.supplier, V.supplier)}>${esc(t('dv_none'))}</option>${s.suppliers.map(c => opt(c.id, c.company ? `${c.name}, ${c.company}` : c.name, V.supplierCur)).join('')}</select>`, { help: esc(t('dv_supplier_help')) })}</div>
    <div class="field-row">
      ${fld(`${fid}-pipeline`, esc(t('lbl_pipeline')), `<select class="select" id="${fid}-pipeline" name="pipeline">${s.pipelines.map(p => opt(p.id, p.name, V.pipelineCur)).join('')}</select>`)}
      ${fld(`${fid}-stage`, esc(t('lbl_stage')), `<select class="select" id="${fid}-stage" name="stage">${krFmDealStageOptions(s)}</select>`)}</div>
    <div class="field-row">
      ${fld(`${fid}-value`, esc(t('lbl_deal_value')), `<div class="input-affix dd-affix"><input class="input" id="${fid}-value" name="value" type="number" min="0" step="any" inputmode="decimal" placeholder="0" value="${esc(V.valueAttr)}"${inv('value')}><span class="affix">EUR</span></div>`)}
      ${fld(`${fid}-urgency`, esc(t('chip_urgency')), `<select class="select" id="${fid}-urgency" name="urgency">${DEAL_URGENCY.map(u => opt(u.value, urgencyLabel(u), V.urgencyCur)).join('')}</select>`)}</div>
    <div class="field-row">
      ${fld(`${fid}-owner`, esc(t('chip_owner')), `<select class="select" id="${fid}-owner" name="owner"><option value=""${krFmEmptyOpt(V.dirty.owner, V.owner)}>${esc(t('unassigned'))}</option>${s.members.map(m => opt(m.id, m.name + (m.id === s.currentUser?.id ? ' ' + t('you_marker') : ''), V.ownerCur)).join('')}</select>`)}
      <div></div></div>
    ${s.dealFields.length ? `<div class="field-row">${s.dealFields.map(f => krFmDealCustomField(s, V, f)).join('')}</div>` : ''}</form>`;
}

// detail-views.js:470 — the footer: Abbrechen [data-close], then the submit button (form="<form id>", outside the form)
function krFmDealFormFooter(o) {
  const s = krFmDealState(o);
  return `<button class="btn btn-secondary" type="button" data-close>${esc(t('btn_cancel'))}</button><button class="btn btn-primary${s.locked ? ' is-save-locked' : ''}" type="submit" form="${s.p}-df"${s.submitting ? ' disabled' : ''}>${esc(s.editing ? t('btn_save_changes') : t('dv_create_deal'))}</button>`;
}

// detail-views.js:469 ui.modal({ title, size: 'md', body: form, footer }) — the whole dialog (.overlay > .modal.md).
function krFmDealForm(o) {
  const s = krFmDealState(o);
  return krModalWrap({ p: s.p, title: s.editing ? t('dv_edit_deal') : t('dv_new_deal'), size: 'md', body: krFmDealFormBody(s), footer: krFmDealFormFooter(s) });
}

// detail-views.js:473-478 — the submit's checks. errs keys: title, value (setErr writes both: a passing field is cleared).
function krFmDealValidate(o) {
  const s = krFmDealState(o), V = krFmDealControls(s);
  const title = V.title.trim(), rawV = V.value.trim(), v = Number(rawV);
  const errs = {};
  if (!title) errs.title = t('dv_err_deal_title'); else if (title.length > 140) errs.title = t('dv_err_title_len');
  if (rawV !== '' && (!isFinite(v) || v < 0)) errs.value = t('dv_err_value');
  const first = Object.keys(errs)[0] || null;
  return { errs, first, focus: first ? `${s.p}-df-${first}` : null };
}
// detail-views.js:479-483 — the body POSTed (PUT in edit mode)
function krFmDealPayload(o) {
  const s = krFmDealState(o), V = krFmDealControls(s);
  const toId = x => (x === '' ? null : +x);
  const title = V.title.trim(), rawV = V.value.trim(), v = Number(rawV);
  return { title, contact_id: toId(V.contact), supplier_id: toId(V.supplier), pipeline_id: +V.pipeline, stage_id: toId(V.stage),
    value: rawV === '' ? null : Math.round(v * 100) / 100, assigned_to: toId(V.owner), urgency: +V.urgency,
    custom_data: Object.fromEntries(s.dealFields.map(f => [f.field_key, V.cf[f.field_key]])) };
}
// detail-views.js:471-483 — Deal erstellen pressed (after the save lock and the submit guard, which the page applies:
// locked for 1 s, submitting for 10 s). → { err, focus } (stay open, re-render with err) | { err: {}, request }.
function krFmDealSubmit(o) {
  const s = krFmDealState(o), val = krFmDealValidate(s);
  if (val.first) return { err: val.errs, focus: val.focus, request: null };
  const body = krFmDealPayload(s);
  return { err: {}, focus: null, request: s.editing ? { method: 'PUT', url: `/api/deals/${s.editing.id}`, body } : { method: 'POST', url: '/api/deals', body } };
}
// detail-views.js:484-489 — the server answered res. Error: toast res.error, the dialog stays. Saved: the dialog closes,
// a new deal makes its pipeline the board's (currentPipelineId), the board reloads when the Deals page is open, toast.
function krFmDealSaved(o, res) {
  const s = krFmDealState(o), body = krFmDealPayload(s);
  if (res && res.error) return { close: false, toast: { text: res.error, action: null } };
  return {
    close: true,
    currentPipelineId: s.editing ? s.currentPipelineId : body.pipeline_id,
    reloadDeals: s.dealsPageActive,
    toast: s.editing ? { text: t('dv_deal_updated'), action: null } : { text: t('dv_deal_created'), action: t('tk_open'), openDeal: res && res.id },
    onSave: true,
  };
}
// routes/deals.js:118-136 (POST: title trimmed; no owner → the creator; value 0 / null → null; urgency clamped 0–4) +
// :68-92 (the GET /api/deals row, joined) — the row the board's reload brings back, for a replica without a server.
// at = created_at/updated_at (ISO). Server code, not proven by the check (kr-forms.md §6).
function krFmDealRow(o, body, res, at) {
  const s = krFmDealState(o);
  const stage = krFmDealStagesFor(s, body.pipeline_id).find(x => x.id === body.stage_id) || null;
  const c = s.contacts.find(x => x.id === body.contact_id) || null, sup = s.suppliers.find(x => x.id === body.supplier_id) || null;
  const assignee = body.assigned_to ? Number(body.assigned_to) : (s.currentUser?.id ?? null);
  const n = parseInt(body.urgency, 10);
  return {
    id: res.id, contact_id: body.contact_id || null, pipeline_id: body.pipeline_id, stage_id: body.stage_id || null, title: String(body.title).trim(),
    value: body.value ? String(body.value) : null, custom_data: body.custom_data || {}, assigned_to: assignee, created_at: at, updated_at: at,
    supplier_id: body.supplier_id || null, urgency: Number.isInteger(n) ? Math.min(4, Math.max(0, n)) : 0,
    contact_name: c ? c.name : null, contact_email: c ? c.email ?? null : null, contact_phone: c ? c.phone ?? null : null, contact_company: c ? c.company ?? null : null,
    supplier_name_val: sup ? sup.name : null, stage_name: stage ? stage.name : null, stage_color: stage ? stage.color : null,
    assigned_to_name: s.members.find(m => m.id === assignee)?.name || null,
  };
}

/* ════════════════════════════════════════════════════════════════════════════════════════════════
   2. THE DEALS LIST VIEW — deals.js:495-582 renderDealsList & co., the page in list mode (setDealView('list'))
   ════════════════════════════════════════════════════════════════════════════════════════════════ */

// o = kr-deals' o (pipelines, pipelineId, deals, members, currentUser, dealFields, summary, q, owner, urgency, stage, cf)
// + the list's own state: sort ({ key, dir }), sel (selected deal ids), dealColumns (users.deal_columns).
// List mode keeps pipelineId null ("Alle Pipelines": deals of every pipeline); an unknown id becomes null
// (deals.js:152-162 populatePipelineSelect without the board's "first pipeline" default).
function krFmListState(o = {}) {
  if (o.krFmList) return o;
  const s = krDealsState({ ...o, krState: false });
  let pipelineId = o.pipelineId ?? null;
  if (pipelineId && !s.pipelines.find(p => p.id === pipelineId)) pipelineId = null;
  return {
    ...s, krFmList: true, pipelineId,
    sort: o.sort || { key: 'created_at', dir: -1 },             // deals.js:93 dealsUI.sort (newest first; the column is hidden by default)
    sel: (o.sel || []).filter(id => s.deals.some(d => d.id === id)),   // deals.js:525: ids no longer loaded drop out
    dealColumns: o.dealColumns || [],                            // currentUser.deal_columns: [{ key, visible }]; [] = the defaults
  };
}

// deals.js:200-217 effectiveDealColumns — [{ key, label, show, visible }] in the drawn order (labels as strings).
function krFmDealColumns(o) {
  const s = krFmListState(o);
  const BUILTIN = [
    { key: 'stage',       label: t('col_stage'),      show: true  },
    { key: 'contact',     label: t('lbl_contact'),    show: true  },
    { key: 'value',       label: t('lbl_deal_value'), show: true  },
    { key: 'urgency',     label: t('col_urgency'),    show: true  },
    { key: 'assigned_to', label: t('col_owner'),      show: true  },
    { key: 'created_at',  label: t('col_created_at'), show: false },
  ];
  const ALL = [...BUILTIN, ...s.dealFields.map(f => ({ key: `custom:${f.field_key}`, label: f.name, show: true }))];
  if (!s.dealColumns.length) return ALL.map(c => ({ ...c, visible: c.show }));
  const savedMap = Object.fromEntries(s.dealColumns.map(c => [c.key, c.visible]));
  const ordered = s.dealColumns
    .map(({ key }) => { const def = ALL.find(c => c.key === key); return def ? { ...def, visible: savedMap[key] } : null; })
    .filter(Boolean);
  ALL.filter(c => !(c.key in savedMap)).forEach(c => ordered.push({ ...c, visible: c.show }));
  return ordered;
}

// deals.js:495-510 sortDeals — a sorted copy (stable; ties keep the API order)
function krFmSortDeals(o, rows) {
  const s = krFmListState(o), { key, dir } = s.sort;
  const val = d => {
    if (key === 'title')       return (d.title || '').toLowerCase();
    if (key === 'stage')       return krDealStagesOf(s.pipelines, d).findIndex(st => st.id === d.stage_id);
    if (key === 'value')       return Number(d.value) || 0;
    if (key === 'urgency')     return parseInt(d.urgency, 10) || 0;
    if (key === 'assigned_to') return (d.assigned_to_name || '').toLowerCase();
    if (key === 'contact')     return (d.contact_name || '').toLowerCase();
    if (key === 'created_at')  return d.created_at || '';
    if (key === 'pipeline')    return (s.pipelines.find(p => p.id === d.pipeline_id)?.name || '').toLowerCase();
    if (key.startsWith('custom:')) return String(d.custom_data?.[key.slice(7)] ?? '').toLowerCase();
    return '';
  };
  return [...rows].sort((a, b) => { const x = val(a), y = val(b); return (x > y ? 1 : x < y ? -1 : 0) * dir; });
}
// the rows the list draws, in order
function krFmDealsListRows(o) { const s = krFmListState(o); return krFmSortDeals(s, krVisibleDeals(s)); }

// deals.js:518-565 renderDealsList — the four hosts it rewrites: { bulkbar, thead, tbody, foot } (innerHTML each).
function krFmDealsListParts(o) {
  const s = krFmListState(o);
  const visibleCols = krFmDealColumns(s).filter(c => c.visible);
  const showPipeline = !s.pipelineId;
  const rows = krFmDealsListRows(s);
  const sel = new Set(s.sel);
  const dash = '<span class="muted">—</span>';

  const th = (key, label, cls = '') => {
    const on = s.sort.key === key;
    return `<th class="${cls}" aria-sort="${on ? (s.sort.dir > 0 ? 'ascending' : 'descending') : 'none'}"><button type="button" data-sort="${key}" data-kr="sort">${esc(label)}${on ? icon(s.sort.dir > 0 ? 'arrow-up' : 'arrow-down', 'ic-sm') : ''}</button></th>`;
  };
  const allSel = rows.length > 0 && rows.every(d => sel.has(d.id));
  const thead = `<tr>
    <th class="col-check"><label class="check"><input type="checkbox" data-all aria-label="${esc(t('filter_all'))}" data-kr="select-all" ${allSel ? 'checked' : ''}></label></th>
    ${th('title', t('col_title'))}${showPipeline ? th('pipeline', t('col_pipeline')) : ''}
    ${visibleCols.map(c => th(c.key, c.label, c.key === 'value' ? 'num-col' : '')).join('')}<th style="width:44px"></th></tr>`;

  const cell = (d, col) => {
    if (col.key === 'stage')       return `<td>${d.stage_name ? `<span class="stage-pill"><i style="background:${esc(d.stage_color || 'var(--border-strong)')}"></i>${esc(d.stage_name)}</span>` : dash}</td>`;
    if (col.key === 'contact')     return `<td style="max-width:260px">${d.contact_name ? `<div class="truncate">${esc(d.contact_name)}</div>${d.contact_company ? `<div class="muted truncate" style="font-size:var(--fs-sm)">${esc(d.contact_company)}</div>` : ''}` : dash}</td>`;
    if (col.key === 'value')       return `<td class="num-col tnum strong">${d.value != null ? fmtEUR(d.value) : dash}</td>`;
    if (col.key === 'urgency')     return `<td>${urgencyBadge(d.urgency) || `<span class="muted">${esc(t('not_set'))}</span>`}</td>`;
    if (col.key === 'assigned_to') return `<td>${d.assigned_to_name ? `<div class="row" style="gap:8px">${avatar(d.assigned_to_name, 'sm')}<span>${esc(d.assigned_to_name.split(' ')[0])}</span></div>` : dash}</td>`;
    if (col.key === 'created_at')  return `<td class="muted">${fmtDateShort(d.created_at)}</td>`;
    if (col.key.startsWith('custom:')) return `<td>${esc(d.custom_data?.[col.key.slice(7)] ?? '') || dash}</td>`;
    return `<td>${dash}</td>`;
  };
  const span = 3 + (showPipeline ? 1 : 0) + visibleCols.length;
  const filtered = krDealsFilterActive(s);
  const tbody = rows.length ? rows.map(d => `<tr class="clickable" aria-selected="${sel.has(d.id)}" data-kr="open-deal" data-kr-id="${d.id}">
      <td class="col-check"><label class="check"><input type="checkbox" data-row="${d.id}" aria-label="${esc(d.title)}" data-kr="select-row" ${sel.has(d.id) ? 'checked' : ''}></label></td>
      <td style="max-width:360px"><div class="truncate" style="font-weight:620">${esc(d.title)}</div></td>
      ${showPipeline ? `<td>${esc(s.pipelines.find(p => p.id === d.pipeline_id)?.name || '') || dash}</td>` : ''}
      ${visibleCols.map(c => cell(d, c)).join('')}
      <td><button class="iconbtn" type="button" style="width:28px;height:28px" data-kebab="${d.id}" data-kr="kebab" aria-label="${esc(t('open_deal'))}: ${esc(d.title)}">${icon('ellipsis')}</button></td>
    </tr>`).join('')
    : `<tr><td colspan="${span}"><div class="empty">${icon('search')}<b>${esc(t(filtered ? 'no_deals_match' : 'no_deals_yet'))}</b>${filtered ? `<div>${esc(t('try_removing_filter'))}</div>` : ''}</div></td></tr>`;

  const bulkbar = sel.size ? `<div class="bulkbar" role="toolbar"><b>${esc(tf('n_selected', { n: sel.size }))}</b>
      <button class="btn btn-sm" type="button" data-kr="bulk" data-kr-arg="stage">${esc(t('move_to_stage'))}</button>
      <button class="btn btn-sm" type="button" data-kr="bulk" data-kr-arg="delete">${esc(t('btn_delete'))}</button>
      <button class="btn btn-sm" type="button" style="margin-left:auto" data-kr="bulk" data-kr-arg="clear">${esc(t('clear_selection'))}</button></div>` : '';
  const foot = `<span>${esc(tf('of_deals', { a: rows.length, b: s.deals.length }))}</span><span class="tnum">${esc(t('total_lbl'))} <b style="color:var(--text)">${fmtEUR(krDealsSum(rows))}</b></span>`;
  return { bulkbar, thead, tbody, foot };
}

// index.html:422-430 #deals-list-view, shown (class "hidden" dropped by setDealView('list')), filled by renderDealsList.
function krFmDealsList(o) {
  const s = krFmListState(o), p = s.p, x = krFmDealsListParts(s);
  return `<div id="${p}-deals-list-view" class="deals-list kr-deals-list-view">
    <div id="${p}-deals-bulkbar">${x.bulkbar}</div>
    <div class="table-wrap">
      <table class="table" id="${p}-deals-table">
        <thead id="${p}-deals-thead">${x.thead}</thead>
        <tbody id="${p}-deals-tbody">${x.tbody}</tbody>
      </table>
    </div>
    <div id="${p}-deals-list-foot" class="table-foot kr-deals-list-foot">${x.foot}</div>
  </div>`;
}

// deals.js:155 in list mode: "Alle Pipelines" first; `selected` stands for sel.value (deals.js:161)
function krFmListPipelineOptions(o) {
  const s = krFmListState(o);
  return `<option value=""${s.pipelineId ? '' : ' selected'}>${esc(t('opt_all_pipelines'))}</option>` +
    s.pipelines.map(p => `<option value="${p.id}"${p.id === s.pipelineId ? ' selected' : ''}>${esc(p.name)}</option>`).join('');
}

// deals.js:313-322 renderDealsToolbar in list mode (the "Spalten" button is drawn). Chips = kr-deals' krDealsChip.
function krFmDealsListToolbar(o) {
  const s = krFmListState(o), p = s.p;
  const any = krDealsFilterActive(s);
  return `<div class="input-group" style="width:260px">${icon('search')}<input class="input" id="${p}-deals-q" type="search" placeholder="${esc(t('search_deals'))}" value="${esc(s.q)}" aria-label="${esc(t('search_deals'))}" data-kr="search"></div>
    ${krDealsChip(s, 'owner')}${krDealsChip(s, 'urgency')}${krDealsChip(s, 'stage')}${krDealFilterFields(s).map(f => krDealsChip(s, 'cf:' + f.field_key, f.name)).join('')}
    ${any ? `<button class="btn btn-ghost btn-sm" type="button" data-kr="clear-filters">${esc(t('clear_filters'))}</button>` : ''}<span class="grow"></span>
    <button class="btn btn-secondary btn-sm" type="button" data-kr="columns" aria-haspopup="menu">${icon('columns')}${esc(t('btn_columns'))}</button>
    <button class="btn btn-secondary btn-sm" type="button" data-kr="toggle-summary" aria-pressed="${s.summary}">${icon('bar-chart')}${esc(t(s.summary ? 'hide_summary' : 'show_summary'))}</button>`;
}

// index.html:403-433 #page-deals after loadDeals() in list mode (deals.js:132-149 + setDealView('list') 173-189):
// the board hidden and empty, the list shown, Board/Liste aria-pressed swapped, the select with "Alle Pipelines".
function krFmDealsListPage(o) {
  const s = krFmListState(o), p = s.p;
  return `<section id="${p}-page-deals" class="page active">
  <div class="page-header">
    <div>
      <h1 class="page-title" data-i18n="nav_deals">${krFmText(t('nav_deals'))}</h1>
      <p class="page-sub" id="${p}-deals-page-sub">${krFmText(krDealsSubText(s))}</p>
    </div>
    <div class="page-actions">
      <select id="${p}-deals-pipeline-select" class="btn btn-secondary deals-pipeline-select" data-kr="pipeline">${krFmListPipelineOptions(s)}</select>
      <div class="seg" role="group" aria-label="${esc(t('tk_view'))}" data-i18n-aria="tk_view">
        <button id="${p}-deal-view-kanban" aria-pressed="false" data-kr="view-board" type="button"><svg class="ic ic-sm" aria-hidden="true"><use href="#i-kanban"/></svg><span data-i18n="view_board">${krFmText(t('view_board'))}</span></button>
        <button id="${p}-deal-view-list" aria-pressed="true" data-kr="view-list" type="button"><svg class="ic ic-sm" aria-hidden="true"><use href="#i-list"/></svg><span data-i18n="view_list">${krFmText(t('view_list'))}</span></button>
      </div>
      <button class="btn btn-secondary btn-icon" data-kr="more" type="button" aria-label="${esc(t('html_more_actions'))}" data-i18n-aria="html_more_actions" aria-haspopup="menu"><svg class="ic" aria-hidden="true"><use href="#i-ellipsis"/></svg></button>
      <button class="btn btn-primary" data-kr="add-deal"><svg class="ic" aria-hidden="true"><use href="#i-plus"/></svg><span data-i18n="add_deal">${krFmText(t('add_deal'))}</span></button>
    </div>
  </div>
  <!-- Summary (KPIs + value by stage), toolbar, then the board or the list. All filled by deals.js. -->
  <section id="${p}-deals-summary" class="card summary${s.summary ? '' : ' hidden'} kr-deals-summary" aria-label="${esc(t('html_pipeline_summary'))}" data-i18n-aria="html_pipeline_summary">${krDealsSummary(s)}</section>
  <div id="${p}-deals-toolbar" class="toolbar">${krFmDealsListToolbar(s)}</div>
  <div id="${p}-deals-board" class="board hidden kr-deals-board"></div>
  ${krFmDealsList(s)}
</section>`;
}

/* ---------- the list's state changes (pure; merge the result into o, then re-render what the note says) ---------- */
// deals.js:511-514 sortDealsBy — same key flips the direction, a new key starts ascending. Re-render: the list parts.
function krFmSortDealsBy(o, key) { const s = krFmListState(o); return { sort: { key, dir: s.sort.key === key ? -s.sort.dir : 1 } }; }
// deals.js:515 toggleDealSelected — re-render: the list parts.
function krFmToggleDealSelected(o, id, on) { const s = krFmListState(o), sel = new Set(s.sel); if (on) sel.add(id); else sel.delete(id); return { sel: [...sel] }; }
// deals.js:516 toggleAllDeals — every VISIBLE deal on or off (hidden selections stay). Re-render: the list parts.
function krFmToggleAllDeals(o, on) { const s = krFmListState(o), sel = new Set(s.sel); krVisibleDeals(s).forEach(d => (on ? sel.add(d.id) : sel.delete(d.id))); return { sel: [...sel] }; }
// deals.js:267-276 openDealsColumnsMenu — ui.menu items ({ align: 'right' }); picking toggles that column
function krFmDealsColumnsItems(o) { return krFmDealColumns(o).map((c, i) => ({ label: c.label, checked: c.visible, act: 'toggle-column', i })); }
// … → dealColumns (then PATCH /api/auth/preferences { deal_columns }). Re-render: the list parts only (not the toolbar).
function krFmToggleDealColumn(o, i) {
  const cols = krFmDealColumns(o);
  cols[i].visible = !cols[i].visible;
  return { dealColumns: cols.map(({ key, visible }) => ({ key, visible })) };
}
// deals.js:572-581 bulkDeals('stage') — the menu at the bulk button (left-aligned): a heading per pipeline when the
// selection spans several, then that pipeline's stages. Items: { label, act: 'bulk-move', pipelineId, stageId }.
function krFmBulkStageItems(o) {
  const s = krFmListState(o), ids = s.sel;
  const selected = s.deals.filter(d => ids.includes(d.id));
  const pids = [...new Set(selected.map(d => d.pipeline_id))];
  return pids.flatMap(pid => {
    const p = s.pipelines.find(x => x.id === pid); if (!p) return [];
    return [...(pids.length > 1 ? [{ heading: p.name }] : []), ...(p.stages || []).map(st => ({ label: st.name, act: 'bulk-move', pipelineId: pid, stageId: st.id }))];
  });
}
// … picking a stage: each selected deal of THAT pipeline not already there moves (applyStage + PATCH, one after the
// other), the whole selection clears, everything re-renders, toast "{n} Deals nach {s} verschoben" (n = the selected
// deals of that pipeline, moved or not). No undo.
function krFmBulkMove(o, pipelineId, stageId) {
  const s = krFmListState(o);
  const mine = s.deals.filter(d => s.sel.includes(d.id) && d.pipeline_id === pipelineId);
  const stage = krDealStagesOf(s.pipelines, { pipeline_id: pipelineId }).find(x => x.id === stageId);
  const moved = mine.filter(d => d.stage_id !== stageId).map(d => d.id);
  let deals = s.deals;
  for (const d of mine) if (d.stage_id !== stageId) deals = krPatchDeal(deals, d.id, krDealStagePatch(s, d, stageId));
  return { deals, sel: [], patches: moved.map(id => ({ url: `/api/deals/${id}/stage`, body: { stage_id: stageId } })), toast: { text: tf('deals_moved_to', { n: mine.length, s: stage ? stage.name : '' }), action: null } };
}
// deals.js:484-492 deleteDeals(ids) — the confirm it asks (krConfirm), and the state after "Löschen".
function krFmDealsDeleteConfirm(ids) {
  return { title: ids.length > 1 ? tf('delete_deals_q', { n: ids.length }) : t('delete_deal_q'), message: t('delete_deal_msg'), confirmLabel: t('btn_delete'), danger: true };
}
function krFmDealsDeleted(o, ids) {
  const s = krFmListState(o);
  return { deals: s.deals.filter(d => !ids.includes(d.id)), sel: s.sel.filter(id => !ids.includes(id)), toast: { text: ids.length > 1 ? tf('deals_deleted', { n: ids.length }) : t('deal_deleted'), action: null } };
}
// deals.js:303-309 jumpToStage in list mode: the strip / legend toggles the stage filter. Re-render: everything.
function krFmListJump(o, stageId) { const s = krFmListState(o); return { stage: s.stage === stageId ? null : stageId }; }

/* ════════════════════════════════════════════════════════════════════════════════════════════════
   3. THE CONTACT DIALOG — index.html:1532-1556 #contact-modal, filled by modals.js:26-58 openContactModal(id)
      Opened by: "Kontakt hinzufügen" (#list-add-btn → openContactModal()), the top bar "Neu › Kontakt" (core.js:1563:
      on the supplier page it first switches to Contacts), the contact record "Bearbeiten" (openContactModal(id)).
   ════════════════════════════════════════════════════════════════════════════════════════════════ */

// objects.js:75 supplierWord(1) — the singular the supplier page's title uses (core_supplier fallback)
function krFmSupplierOne(o) { const w = o && o.workspace && o.workspace.supplier_name; return w ? w.replace(/s$/i, '') : t('core_supplier'); }

// o (see kr-forms.md §2.3): p, contactType ('contact' | 'supplier'), workspace, fields, members, currentUser,
// contact (edit mode: GET /api/contacts/:id), values (the user's typing), error, errorShown, locked, submitting, activePage.
function krFmContactState(o = {}) {
  if (o.krFmContact) return o;
  return {
    krFmContact: true, p: o.p || 'kr', contactType: o.contactType || 'contact', workspace: o.workspace || null,
    fields: o.fields || [], members: o.members || [], currentUser: o.currentUser || null, contact: o.contact || null,
    values: o.values || {},                       // { name, company, email, phone, assignee, cf: { key: v } }
    error: o.error || null,                       // null | 'email_taken' | 'save' — the line under the form (kept after a reopen)
    errorShown: o.errorShown ?? !!o.error,        // the line is visible (saveContact) or hidden again (a reopen)
    locked: !!o.locked, submitting: !!o.submitting, activePage: o.activePage || 'contacts',
  };
}

// modals.js:60-67 renderFieldInput(f, value) — note the line break and indentation inside the dropdown's markup
function krFmContactFieldInput(f, value) {
  const id = `cfield-${f.field_key}`;
  if (f.type === 'dropdown') return `<select id="${id}"><option value="">${esc(t('md_opt_select'))}</option>
    ${(f.options||[]).map(o => `<option value="${esc(o)}" ${value===o?'selected':''}>${esc(o)}</option>`).join('')}
  </select>`;
  const typeMap = { text:'text', email:'email', phone:'tel', number:'number', date:'date', url:'url' };
  return `<input type="${typeMap[f.type]||'text'}" id="${id}" value="${esc(value)}" />`;
}

// What each control holds: { set: which ones were written through .value (they show it as an attribute), values }.
function krFmContactControls(o) {
  const s = krFmContactState(o), c = s.contact, v = s.values, cfv = v.cf || {};
  const set = {}, val = { name: '', company: '', email: '', phone: '', assignee: '', cf: {} };
  if (c) { Object.assign(val, { name: c.name, company: c.company || '', email: c.email || '', phone: c.phone || '', assignee: c.assigned_to || '' }); set.name = set.company = set.email = set.phone = true; }
  else val.assignee = s.currentUser?.id || '';
  set.assignee = true;
  for (const k of ['name', 'company', 'email', 'phone']) if (Object.prototype.hasOwnProperty.call(v, k)) { val[k] = v[k]; set[k] = true; }
  if (Object.prototype.hasOwnProperty.call(v, 'assignee')) val.assignee = v.assignee;
  val.assignee = String(val.assignee ?? '');
  if (val.assignee !== '' && !s.members.some(m => String(m.id) === val.assignee)) { val.assignee = ''; val.assigneeNone = true; }   // no option matches: none selected, .value ''
  const types = { name: 'text', company: 'text', email: 'email', phone: 'tel' };
  for (const k of Object.keys(types)) val[k] = krFmSanitize(types[k], val[k]);
  set.cf = {}; set.cfNone = {};
  for (const f of s.fields) {
    const k = f.field_key, typed = Object.prototype.hasOwnProperty.call(cfv, k);
    let x = c ? (c.custom_data?.[k] ?? '') : '';
    if (typed) x = cfv[k];
    if (c || typed) set.cf[k] = true;
    if (f.type === 'dropdown') {
      const sv = String(x);
      // a value no option has (an option deleted since): none selected, .value ''
      if (set.cf[k] && sv !== '' && !(f.options || []).includes(sv)) { set.cfNone[k] = true; val.cf[k] = ''; } else val.cf[k] = set.cf[k] ? sv : '';
    } else val.cf[k] = krFmSanitize(KR_FM_CF_TYPES[f.type] || 'text', x);
  }
  return { set, val };
}
// the assignee <select>'s options (modals.js:37-38), the current one marked `selected` (assigneeEl.value = …)
function krFmContactAssigneeOptions(o) {
  const s = krFmContactState(o), V = krFmContactControls(s).val, cur = V.assigneeNone ? null : V.assignee;
  return `<option value=""${cur === '' ? ' selected' : ''}>${esc(t('opt_unassigned'))}</option>` +
    s.members.map(m => `<option value="${m.id}"${cur !== null && String(m.id) === cur ? ' selected' : ''}>${esc(m.name)}${m.id === s.currentUser?.id ? ' ' + esc(t('you_marker')) : ''}</option>`).join('');
}
// modals.js:40-41 #cf-custom-fields — renderFieldInput(f, ''), then (edit mode / typing) the value the control holds
function krFmContactCustomFields(o) {
  const s = krFmContactState(o), C = krFmContactControls(s);
  return s.fields.map(f => {
    let input = krFmContactFieldInput(f, '');
    if (C.set.cf[f.field_key] && !C.set.cfNone[f.field_key]) {
      const v = C.val.cf[f.field_key];
      if (f.type === 'dropdown') input = v === '' ? input.replace('<option value="">', '<option value="" selected>') : krFmContactFieldInput(f, v);
      else input = input.replace(/ value="[^"]*" \/>$/, ` value="${esc(v)}" />`);
    }
    return `<div class="field"><label class="label" for="cfield-${f.field_key}">${esc(f.name)}</label>${input}</div>`;
  }).join('').replace(/(\s)(id|for)="(cfield-[^"]*)"/g, (m, sp, a, id) => `${sp}${a}="${s.p}-${id}"`);
}

// index.html:1532-1556 as openContactModal(id) leaves it: shown, title "Kontakt hinzufügen" / "Kontakt bearbeiten"
// (supplier page: the workspace word), hidden ids set, the assignee list, the custom fields, and the error line.
function krFmContactModal(o) {
  const s = krFmContactState(o), p = s.p, C = krFmContactControls(s), set = C.set, V = C.val;
  const typeName = s.contactType === 'supplier' ? krFmSupplierOne(s) : t('lbl_contact');
  const title = s.contact ? tf('obj_edit_item', { name: typeName }) : tf('obj_add_item', { name: typeName });
  const val = k => (set[k] ? ` value="${esc(V[k])}"` : '');
  const taken = s.errorShown && s.error === 'email_taken';
  const errText = s.error ? t(s.error === 'email_taken' ? 'cf_err_email_taken' : 'cf_err_save') : '';
  return `<div id="${p}-contact-modal" class="modal-overlay">
  <div class="modal">
    <div class="modal-head">
      <h2 class="modal-title" id="${p}-contact-modal-title" data-i18n="add_contact_title">${krFmText(title)}</h2>
      <button class="iconbtn" data-kr="contact-close" aria-label="${esc(t('btn_close'))}" data-i18n-aria="btn_close"><svg class="ic" aria-hidden="true"><use href="#i-x"/></svg></button>
    </div>
    <form id="${p}-contact-form" data-kr="contact-save">
      <input type="hidden" id="${p}-contact-id" value="${esc(s.contact ? s.contact.id : '')}" />
      <input type="hidden" id="${p}-cf-type" value="${esc(s.contactType)}" />
      <div class="modal-body" id="${p}-contact-modal-body">
        <div class="field"><label class="label" for="${p}-cf-name"><span data-i18n="lbl_name">${krFmText(t('lbl_name'))}</span> <span class="req">*</span></label><input type="text" id="${p}-cf-name" required${val('name')} /></div>
        <div class="field"><label class="label" for="${p}-cf-company" data-i18n="lbl_company">${krFmText(t('lbl_company'))}</label><input type="text" id="${p}-cf-company"${val('company')} /></div>
        <div class="field"><label class="label" for="${p}-cf-email" data-i18n="lbl_email">${krFmText(t('lbl_email'))}</label><input type="email" id="${p}-cf-email" aria-describedby="${p}-cf-error"${taken ? ' aria-invalid="true"' : ''}${val('email')} /></div>
        <div class="field"><label class="label" for="${p}-cf-phone" data-i18n="lbl_phone">${krFmText(t('lbl_phone'))}</label><input type="tel" id="${p}-cf-phone"${val('phone')} /></div>
        <div class="field"><label class="label" for="${p}-cf-stage" data-i18n="lbl_stage">${krFmText(t('lbl_stage'))}</label><select id="${p}-cf-stage"></select></div>
        <div class="field"><label class="label" for="${p}-cf-assignee" data-i18n="lbl_assignee">${krFmText(t('lbl_assignee'))}</label><select id="${p}-cf-assignee">${krFmContactAssigneeOptions(s)}</select></div>
        <div id="${p}-cf-custom-fields" class="col">${krFmContactCustomFields(s)}</div>
        <p class="error-text" id="${p}-cf-error" role="alert"${s.errorShown ? '' : ' hidden'}>${krFmText(errText)}</p>
      </div>
      <div class="modal-foot">
        <button type="button" class="btn btn-secondary" data-kr="contact-close" data-i18n="btn_cancel">${krFmText(t('btn_cancel'))}</button>
        <button type="submit" class="btn btn-primary${s.locked ? ' is-save-locked' : ''}" data-i18n="btn_save"${s.submitting ? ' disabled' : ''}>${krFmText(t('btn_save'))}</button>
      </div>
    </form>
  </div>
</div>`;
}

// The browser's constraint validation (the form has no novalidate, so it runs before saveContact): the first control
// that fails, in tree order, gets focus and a native bubble; nothing in the markup changes and no request is made.
// → { id, reason: 'valueMissing' | 'typeMismatch' } | null. Spec rules, not app code (kr-forms.md §6).
const KR_FM_EMAIL_RE = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/;
function krFmValidUrl(v) { try { const u = new URL(v); return !!u.protocol; } catch { return false; } }
function krFmContactInvalid(o) {
  const s = krFmContactState(o), V = krFmContactControls(s).val, p = s.p;
  if (V.name === '') return { id: `${p}-cf-name`, reason: 'valueMissing' };
  if (V.email !== '' && !KR_FM_EMAIL_RE.test(V.email)) return { id: `${p}-cf-email`, reason: 'typeMismatch' };
  for (const f of s.fields) {
    const v = V.cf[f.field_key];
    if (v === '') continue;
    if (f.type === 'email' && !KR_FM_EMAIL_RE.test(v)) return { id: `${p}-cfield-${f.field_key}`, reason: 'typeMismatch' };
    if (f.type === 'url' && !krFmValidUrl(v)) return { id: `${p}-cfield-${f.field_key}`, reason: 'typeMismatch' };
  }
  return null;
}
// modals.js:72-81 — the body saveContact sends (assigned_to stays the option's STRING value; '' → null)
function krFmContactPayload(o) {
  const s = krFmContactState(o), V = krFmContactControls(s).val;
  return { name: V.name, company: V.company, email: V.email, phone: V.phone, assigned_to: V.assignee || null,
    contact_type: s.contactType, custom_data: Object.fromEntries(s.fields.map(f => [f.field_key, V.cf[f.field_key]])) };
}
// modals.js:82-100 — Speichern pressed and the browser let it through: the request …
function krFmContactSubmit(o) {
  const s = krFmContactState(o), body = krFmContactPayload(s);
  return s.contact ? { method: 'PUT', url: `/api/contacts/${s.contact.id}`, body } : { method: 'POST', url: '/api/contacts', body };
}
// … and the answer. Refused: the dialog stays, the line says why (email taken: the email field marked + focused).
// Saved: the line hidden, the dialog closed (closeModal: also re-enables its submit button), the caches dropped
// (invalidate), then the Deals page reloads its deals or else the Contacts list reloads. No toast.
function krFmContactSaved(o, res) {
  const s = krFmContactState(o);
  if (!res || res.error) {
    const taken = res?.code === 'email_taken';
    return { close: false, error: taken ? 'email_taken' : 'save', errorShown: true, focus: taken ? `${s.p}-cf-email` : null };
  }
  return { close: true, errorShown: false, invalidate: true, reload: s.activePage === 'deals' ? 'deals' : 'contacts', toast: null };
}
// routes/contacts.js:206-235 POST / :237-258 PUT — would the server answer 409 email_taken? all = every contact of the
// workspace, of ANY type (suppliers count). Create: the lower-cased, trimmed address equals a stored one. Edit: a new
// address (not the contact's own in any spelling) that another contact has, case-insensitively. Server code (§6).
function krFmContactEmailTaken(all, email, ownId = null) {
  const typed = typeof email === 'string' ? email.toLowerCase().trim() : '';
  if (!typed) return false;
  if (ownId == null) return (all || []).some(c => c.email === typed);
  const own = String((all || []).find(c => c.id === ownId)?.email || '').toLowerCase().trim();
  if (typed === own) return false;
  return (all || []).some(c => c.id !== ownId && String(c.email || '').toLowerCase() === typed);
}
// routes/contacts.js:206-235 + :60-73 — the row the list's reload brings back for a new contact (the fields
// kr-contacts draws). No owner → the creator; email lower-cased and trimmed; '' → null. at = created_at (ISO).
function krFmContactRow(o, body, res, at) {
  const s = krFmContactState(o);
  const assignee = body.assigned_to ? Number(body.assigned_to) : (s.currentUser?.id ?? null);
  const m = s.members.find(x => x.id === assignee);
  return {
    id: res.id, name: body.name, email: body.email ? body.email.toLowerCase().trim() : null, phone: body.phone || null, company: body.company || null,
    stage_id: null, assigned_to: assignee, custom_data: body.custom_data || {}, created_at: at, updated_at: at, contact_type: body.contact_type || 'contact',
    assigned_to_name: m ? m.name : null, assigned_to_email: m ? m.email ?? null : null, last_activity_at: null,
  };
}


/* ════ record ════ */
/* kr-record.js — the deal record (openDealDetail, public/js/detail-views.js:501-864) as pure renderers.
   Concatenated after kr-core.js. Every template literal below is copied from the app; the only changes are
   (a) inline handlers / draggable removed (this screen has none), (b) every id / for / aria-labelledby gets
   the `${p}-` prefix, (c) helper calls renamed to their krRec* copies, which take the app's globals
   (currentUser, currentWorkspace, members, objects, objectFields, dealFields) as arguments.
   Proven byte-identical to the app's own render by kr-record.check.js. Notes: kr-record.md. */

/* ───────────── shared helpers (detail-views.js:56-253), krRec copies ───────────── */

// detail-views.js:56-62
