/* ───────────── public renderers ───────────── */
const KR_REC_PARTS = { top: krRecTopHtml, head: krRecHeadHtml, main: krRecMainHtml, side: krRecSideHtml };

// What render(parts) writes into one container (detail-views.js:715-725): part = 'top' → #${p}-dd-top,
// 'head' → #${p}-dd-head, 'main' → #${p}-dd-main, 'side' → #${p}-dd-side (each container's innerHTML).
function krDealRecordPart(o, part) { return KR_REC_PARTS[part](krRecCtx(o)); }

// The modal body: #dd-root with its four containers filled (the ui.modal body string, detail-views.js:704-705,
// after render() at :862).
function krDealRecordInner(o) {
  const X = krRecCtx(o), p = X.p;
  return `<div class="dd" id="${p}-dd-root"><div id="${p}-dd-top">${krRecTopHtml(X)}</div><section class="card dd-head" id="${p}-dd-head" aria-label="${esc(t('dv_deal_summary'))}">${krRecHeadHtml(X)}</section>
      <div class="split split-2-1"><section class="card dd-main" id="${p}-dd-main">${krRecMainHtml(X)}</section><div class="dd-side" id="${p}-dd-side">${krRecSideHtml(X)}</div></div></div>`;
}

// The pop window, core.js:1486-1492 (uiOverlay, the modal branch): `.overlay` > `.modal.xl` + `.dd-modal`
// (classList.add, detail-views.js:707), title = the deal title (render(), :723), no footer.
// The app's id is 'dlg-' + 7 random characters (core.js:1414, 1489); here it is `${p}-dlg`.
function krRecordModal(o, body) {
  const p = o.p || 'kr', size = o.size || 'xl', cls = o.cls == null ? 'dd-modal' : o.cls, id = `${p}-dlg`, footer = o.footer || '';
  return `<div class="overlay"><div class="modal ${size}${cls ? ' ' + cls : ''}" role="dialog" aria-modal="true" aria-labelledby="${id}"><div class="modal-head"><h2 class="modal-title" id="${id}">${esc(o.title)}</h2><button class="iconbtn" data-close aria-label="${esc(t('btn_close'))}">${icon('x')}</button></div><div class="modal-body">${body}</div>${footer ? `<div class="modal-foot">${footer}</div>` : ''}</div></div>`;
}

// The whole record in its pop window.
function krDealRecord(o) { return krRecordModal({ p: o.p, title: o.deal.title }, krDealRecordInner(o)); }

// The composer form alone (form#${p}-dd-compose: segments, hint row, textarea, error, help + save button).
function krComposer(o) { return krRecComposeHtml(krRecCtx(o)); }

// One timeline entry (div.tl-item[data-aid]); o gives the deal (other-deal badge) and the editor state.
function krTimelineItem(a, o) { return krRecTlItem(krRecCtx(o), a); }

// The toast (core.js:1523-1529): <div class="toasts" role="status" aria-live="polite"> holds up to three.
function krRecordToast(message, actionLabel) { return `<div class="toast"><span>${esc(message)}</span>${actionLabel ? `<button>${esc(actionLabel)}</button>` : ''}</div>`; }

/* ───────────── behaviour helpers (pure) ───────────── */
// The counts the record shows (headHtml :567/575, tabsHtml :581-582, activityHtml :631).
function krActivityCounts(o) {
  const X = krRecCtx(o), S = X.S, all = S.acts, list = S.filter ? all.filter(a => a.type === S.filter) : all;
  const openTasks = S.tasks.filter(x => x.status !== krRecDoneKey(X.ws)).length, last = all[0]?.created_at || S.d.updated_at;
  return {
    total: all.length, shown: list.length, openTasks,
    activityBadge: all.length || null,              // the Aktivität tab badge (none at 0)
    tasksBadge: openTasks || null,                  // the Aufgaben tab badge
    entries: S.filter ? tf('tk_n_of_total', { n: list.length, total: all.length }) : krRecPlural(all.length, 'dv_one_entry', 'dv_n_entries'),   // "3 Einträge"
    kpiFoot: krRecPlural(all.length, 'dv_one_logged_activity', 'dv_n_logged_activities'),   // "3 erfasste Aktivitäten"
    lastActivity: last ? agoDays(last) : t('dv_never'),   // "Heute"
  };
}
// The stepper and the Phase KPI (stepperHtml :561-564, headHtml :572).
function krStageStep(o) {
  const X = krRecCtx(o), stages = X.pipe().stages, cur = stages.findIndex(s => s.id === X.S.d.stage_id), st = X.stage();
  return {
    pos: cur + 1, total: stages.length, stage: st,
    label: st ? tf('dv_stage_pos', { a: cur + 1, b: stages.length }) : '',   // "Phase 4 von 5"
    steps: stages.map((s, i) => ({ id: s.id, name: s.name, state: i === cur ? 'current' : i < cur ? 'done' : '', ariaLabel: i === cur ? tf('dv_current_stage', { s: s.name }) : tf('dv_move_to_stage', { s: s.name }) })),
  };
}
// A stepper click (move, :534-543): null when the stage is the current one or unknown; otherwise the deal
// with the new stage, the toast and what Rückgängig moves back to.
function krRecMove(o, stageId) {
  const X = krRecCtx(o), s = X.pipe().stages.find(x => x.id === stageId), d = X.S.d;
  if (!s || d.stage_id === stageId) return null;
  return { deal: Object.assign({}, d, { stage_id: s.id, stage_name: s.name, stage_color: s.color }), undoTo: d.stage_id, toast: tf('moved_to', { s: s.name }), action: t('undo') };
}
// Ctrl/Cmd+Enter or the save button (submitCompose, :754-762): null without a contact (nothing happens),
// { error } for empty text (re-render with compose.err = true, no toast), else the row the next
// GET /api/activities returns first, and the toast "{Typ} erfasst".
function krRecSubmit(o, newId) {
  const X = krRecCtx(o), S = X.S, c = X.contactOf(), text = S.text.trim(), ty = krRecTypeOf(S.type);
  if (!c) return null;
  if (!text) return { error: t('act_err_text') };
  const d = S.d;
  return {
    entry: { id: newId, contact_id: c.id, type: S.type, content: esc(text).replace(/\n/g, '<br>'), created_at: new Date().toISOString(), source: null, cancelled_at: null, calcom_uid: null, contact_name: c.name, bound_deal_id: d.id, deal_id: d.id, deal_title: d.title, logged_by_name: X.currentUser?.name || null },
    toast: tf('act_logged', { type: t(ty.label) }),
  };
}
// GET /api/activities for this record (loadActs :517-520 + routes/activities.js:125-155): the contact's whole
// history, or with thisDealOnly (or no contact) this deal's rows plus the contact's rows tied to no deal.
function krRecActivitiesFor(rows, deal, thisDealOnly) {
  const bound = thisDealOnly || !deal.contact_id;
  return rows.filter(a => bound ? (a.bound_deal_id === deal.id || (a.bound_deal_id == null && deal.contact_id != null && a.contact_id === deal.contact_id)) : a.contact_id === deal.contact_id)
    .slice().sort((a, b) => new Date(b.created_at) - new Date(a.created_at)).slice(0, 200);
}


/* ════ booking ════ */
/* kr-booking.js — the Cal.com booking dialog ("Termin mit {name} buchen"), as pure renderers.
   Ported from public/js/detail-views.js openCalcomBooking (267–426, branch v2.3.2) and the modal shell of
   public/js/core.js uiOverlay (1486–1513). Concatenated after kr-core.js (t, tf, esc, icon, currentLang).
   Template literals are verbatim; the only changes: every id="X" / for="X" / aria-labelledby="X" is
   "${p}-X" (p = o.p), and the random 'dlg-' + uid() of the title is the fixed "${p}-dlg".
   Proof: kr-booking.check.js renders the app's real dialog and these functions side by side. */

// detail-views.js:257 — the Notetaker box and its health check are shown
const KR_BOOKING_NOTETAKER_SHOWN = true;
// clock.js:51 — the zone of a stored row written before its zone was recorded (event_tz NULL)
const KR_BOOKING_DEFAULT_TZ = 'Europe/Berlin';
// detail-views.js:301
const KR_BOOKING_APPS = { 'cal-video': 'Cal Video', 'google-meet': 'Google Meet', zoom: 'Zoom', 'office365-video': 'Microsoft Teams', jitsi: 'Jitsi', 'webex-video': 'Webex', 'whereby-video': 'Whereby' };
// detail-views.js:307
const KR_BOOKING_NT_DOWN = { unreachable: 'cal_rec_down_unreachable', token: 'cal_rec_down_token', error: 'cal_rec_down_error' };
// detail-views.js:263 (inside dvNotetakerToast)
const KR_BOOKING_NT_TOAST = { scheduled: 'cal_rec_scheduled', queued: 'cal_rec_queued', updated: 'cal_rec_updated', duplicate: 'cal_rec_duplicate', waiting_link: 'cal_rec_waiting' };

// ── clock: the app's zone helpers, verbatim, with the viewer's zone passed in ───────────────────────────
// clock.js:65-78 nowInTimezone (tz explicit; the app defaults it to currentTimezone())
function krBookingNowInTz(tz, at = new Date()) {
  try {
    const p = {};
    for (const part of new Intl.DateTimeFormat('en-GB', {
      timeZone: tz, hourCycle: 'h23',
      year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit',
    }).formatToParts(at)) {
      if (part.type !== 'literal') p[part.type] = Number(part.value);
    }
    return new Date(p.year, p.month - 1, p.day, p.hour, p.minute, p.second);
  } catch {
    return at;
  }
}
// clock.js:80
function krBookingPad2(n) { return String(n).padStart(2, '0'); }
// clock.js:84-87
function krBookingTzOffset(tz, instant) {
  const w = krBookingNowInTz(tz, instant);
  return (Date.UTC(w.getFullYear(), w.getMonth(), w.getDate(), w.getHours(), w.getMinutes(), w.getSeconds()) - instant.getTime()) / 60000;
}
// clock.js:94-107
function krBookingInstantOf(date, time, tz) {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(date || ''));
  const t = /^(\d{2}):(\d{2})/.exec(String(time || ''));
  if (!m) return null;
  const guess = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3], t ? +t[1] : 0, t ? +t[2] : 0));
  try {
    const o1 = krBookingTzOffset(tz, guess);
    let inst = new Date(guess.getTime() - o1 * 60000);
    const o2 = krBookingTzOffset(tz, inst);
    if (o2 !== o1) inst = new Date(guess.getTime() - o2 * 60000);
    return inst;
  } catch {
    return guess;
  }
}
// clock.js:114-121
function krBookingWallClock(date, time, fromTz, toTz) {
  const d = String(date || '').slice(0, 10);
  if (!time) return { date: d, time: null };
  const inst = krBookingInstantOf(d, time, fromTz);
  if (!inst) return { date: d, time: null };
  const w = krBookingNowInTz(toTz, inst);
  return { date: `${w.getFullYear()}-${krBookingPad2(w.getMonth() + 1)}-${krBookingPad2(w.getDate())}`, time: `${krBookingPad2(w.getHours())}:${krBookingPad2(w.getMinutes())}` };
}
// clock.js:127-129 toViewerClock (viewerZone = users.timezone, the app's currentTimezone())
function krBookingToViewerClock(date, time, tz, viewerZone) {
  return krBookingWallClock(date, time, tz || KR_BOOKING_DEFAULT_TZ, viewerZone);
}
// detail-views.js:182 dvIsoDateIn — today's date in a zone; `at` makes it pure (the app reads now)
function krBookingIsoDateIn(zone, at = new Date()) { return new Intl.DateTimeFormat('en-CA', { timeZone: zone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(at); }
// detail-views.js:183 dvAddDays
function krBookingAddDays(iso, n) { const d = new Date(iso + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); }
// detail-views.js:185-189 dvZonedParts
function krBookingZonedParts(iso, zone) {
  const p = new Intl.DateTimeFormat('en-CA', { timeZone: zone, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(iso));
  const g = k => p.find(x => x.type === k)?.value;
  return { date: `${g('year')}-${g('month')}-${g('day')}`, time: `${g('hour')}:${g('minute')}` };
}

// ── the dialog's own formatters (detail-views.js:278, 282–307), o passed explicitly ──────────────────────
// :278 — the app fixes the locale when the dialog opens; here it is read from currentLang on every call
function krBookingLocale() { return currentLang === 'de' ? 'de-DE' : 'en-GB'; }
// :282 "14:00"
function krBookingFmtTime(o, iso) { return new Date(iso).toLocaleTimeString(krBookingLocale(), { hour: '2-digit', minute: '2-digit', timeZone: o.zone }); }
// :284 "2:00 PM" (always en-US)
function krBookingFmtAmPm(o, iso) { return new Date(iso).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: o.zone }); }
// :285 'HH:MM' → "2:00 PM"
function krBookingAmpmOf(hhmm) { const d = new Date(Date.UTC(2000, 0, 1, Number(hhmm.slice(0, 2)), Number(hhmm.slice(3, 5)))); return d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: 'UTC' }); }
// :286 'YYYY-MM-DD' → "Di., 27. Okt." / "Tue 27 Oct"
function krBookingFmtDay(iso) { return new Date(iso + 'T12:00:00Z').toLocaleDateString(krBookingLocale(), { weekday: 'short', day: 'numeric', month: 'short' }); }
// :287 ISO instant → "Di., 27. Okt., 14:00" / "Tue 27 Oct, 14:00"
function krBookingFmtWhen(o, iso) { return new Date(iso).toLocaleString(krBookingLocale(), { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: o.zone }); }
// :289 'YYYY-MM' → "Oktober 2026"
function krBookingMonthTitle(ym) { return new Date(ym + '-01T12:00:00Z').toLocaleDateString(krBookingLocale(), { month: 'long', year: 'numeric' }); }
// :290
function krBookingDaysInMonth(ym) { return new Date(Date.UTC(Number(ym.slice(0, 4)), Number(ym.slice(5, 7)), 0)).getUTCDate(); }
// :291
function krBookingAddMonths(ym, n) { return new Date(Date.UTC(Number(ym.slice(0, 4)), Number(ym.slice(5, 7)) - 1 + n, 1)).toISOString().slice(0, 7); }
// :292 blanks before the 1st, Monday first
function krBookingLead(ym) { return (new Date(ym + '-01T00:00:00Z').getUTCDay() + 6) % 7; }
// :293 the weekday heads, Monday first ("Mo".."So" / "Mon".."Sun")
function krBookingDows() { return Array.from({ length: 7 }, (_, i) => new Date(Date.UTC(2024, 0, 1 + i)).toLocaleDateString(krBookingLocale(), { weekday: 'short', timeZone: 'UTC' })); }
// :277 (and :421 after the fresh re-read)
function krBookingTypes(o) { return Array.isArray(o.cal.event_types) && o.cal.event_types.length ? o.cal.event_types : [o.cal.event_type]; }
// :294
function krBookingTypeOf(o) { return krBookingTypes(o).find(x => x.id === o.B.typeId) || o.cal.event_type; }
// :295 a slot's end: its own, else start + the type's length
function krBookingSlotEnd(o, s) { return s.end || new Date(new Date(s.start).getTime() + (krBookingTypeOf(o).lengthInMinutes || 30) * 60000).toISOString(); }
// :296
function krBookingSlotsOf(o, d) { return (o.B.slots && o.B.slots[d]) || []; }
// :297
function krBookingMonthDays(o) { return Array.from({ length: krBookingDaysInMonth(o.B.month) }, (_, i) => `${o.B.month}-${String(i + 1).padStart(2, '0')}`); }
// :298
function krBookingBookable(o, d) { return d >= o.todayIso && krBookingSlotsOf(o, d).length > 0; }
// :300
function krBookingPlacesOf(o) { const ty = krBookingTypeOf(o); return (Array.isArray(ty.locations) ? ty.locations : []).filter(l => l && (l.type === 'integration' ? !!l.integration : ['address', 'link', 'phone'].includes(l.type))); }
// :302
function krBookingPlaceLabel(l) { return l.type === 'integration' ? (KR_BOOKING_APPS[l.integration] || l.integration) : l.type === 'address' ? (l.address ? tf('cal_loc_address', { address: l.address }) : t('cal_loc_address_plain')) : l.type === 'link' ? t('cal_loc_link') : t('cal_loc_phone'); }
// :303
function krBookingPlaceOf(o) { return krBookingPlacesOf(o)[o.B.loc] || null; }
// :305
function krBookingIsMeet(l) { return !!l && l.type === 'integration' && l.integration === 'google-meet'; }

// ── state helpers (what the app's handlers compute) ────────────────────────────────────────────────────
// :281 the state the dialog opens with
function krBookingInitialState({ cal, todayIso, reschedule = null }) {
  return { month: todayIso.slice(0, 7), typeId: (reschedule && reschedule.calcom_event_type_id) || cal.event_type.id, slots: null, loading: true, date: '', picked: null, conflicts: [], checking: false, note: '', err: '', busy: false, loc: 0, record: false, nt: 'idle', ntWhy: '' };
}
// :367 the day preselected once the month's slots arrive
function krBookingFirstDay(o) { return krBookingMonthDays(o).find(d => krBookingBookable(o, d)) || ''; }
// :349 true → the app starts the Notetaker check right after this render (nt becomes 'checking')
function krBookingWantsNotetakerCheck(o) { return KR_BOOKING_NOTETAKER_SHOWN && !o.reschedule && krBookingIsMeet(krBookingPlaceOf(o)) && o.B.nt === 'idle'; }

// ── the renderers ─────────────────────────────────────────────────────────────────────────────────────
// :308 the dialog title
function krBookingTitle(o) { return tf(o.reschedule ? 'cal_resched_title' : 'cal_book_title', { name: o.contact.name }); }

// :311–345 render(): the .cal-book host's innerHTML
function krBookingBody(o) {
  const p = o.p, B = o.B, cal = o.cal, contact = o.contact, zone = o.zone, todayIso = o.todayIso, reschedule = o.reschedule || null;
  const types = krBookingTypes(o), typeOf = () => krBookingTypeOf(o);
  const fmtTime = iso => krBookingFmtTime(o, iso), fmtAmPm = iso => krBookingFmtAmPm(o, iso), ampmOf = krBookingAmpmOf, fmtDay = krBookingFmtDay;
  const monthTitle = krBookingMonthTitle, lead = krBookingLead, dows = krBookingDows();
  const slotEnd = s => krBookingSlotEnd(o, s), slotsOf = d => krBookingSlotsOf(o, d), monthDays = () => krBookingMonthDays(o), bookable = d => krBookingBookable(o, d);
  const placeLabel = krBookingPlaceLabel, isMeet = krBookingIsMeet, NT_DOWN = KR_BOOKING_NT_DOWN, DV_NOTETAKER_SHOWN = KR_BOOKING_NOTETAKER_SHOWN;
  const toViewerClock = (date, time, tz) => krBookingToViewerClock(date, time, tz, zone);
  // ↓ verbatim from detail-views.js:312–345, ids prefixed
  const places = krBookingPlacesOf(o), place = krBookingPlaceOf(o);
  const field = (id, labelKey, control) => `<div class="field"><label class="label" for="${p}-${id}">${esc(t(labelKey))}</label>${control}</div>`;
  const typeSel = field('cal-book-type', 'cal_book_type', `<select class="select" id="${p}-cal-book-type">${types.map(x => `<option value="${Number(x.id)}"${x.id === B.typeId ? ' selected' : ''}>${esc(x.title)}${x.lengthInMinutes ? ` (${esc(tf('cal_minutes', { n: x.lengthInMinutes }))})` : ''}</option>`).join('')}</select>`);
  const whereSel = places.length ? field('cal-book-where', 'cal_book_where', `<select class="select" id="${p}-cal-book-where">${places.map((l, i) => `<option value="${i}"${i === B.loc ? ' selected' : ''}>${esc(placeLabel(l))}</option>`).join('')}</select>`) : '';
  const current = reschedule && reschedule.event_date ? toViewerClock(reschedule.event_date, reschedule.event_time || '00:00', reschedule.event_tz) : null;
  const what = reschedule
    ? `<div class="cal-book-sec"><div class="field-row">${field('cal-book-type', 'cal_book_type', `<input type="text" id="${p}-cal-book-type" class="input" readonly value="${esc(typeOf().title || '')}">`)}<div class="field"><span class="label">${esc(t('cal_resched_current'))}</span><input type="text" class="input" readonly value="${esc(current ? `${fmtDay(current.date)}, ${current.time} (${ampmOf(current.time)})` : '')}"></div></div></div>`
    : `<div class="cal-book-sec"><div class="field-row">${typeSel}${whereSel}</div></div>`;
  const ntOk = B.nt === 'ok';
  const ntLine = ntOk ? esc(t('cal_book_record_help'))
    : B.nt === 'down' ? `${esc(t(NT_DOWN[B.ntWhy] || NT_DOWN.error))} <button type="button" class="btn btn-ghost btn-sm" id="${p}-cal-book-recheck">${esc(t('cal_rec_recheck'))}</button>`
    : esc(t('cal_rec_checking'));
  const rec = DV_NOTETAKER_SHOWN && !reschedule && isMeet(place) ? `<div class="cal-book-sec"><label class="check"><input type="checkbox" id="${p}-cal-book-record"${ntOk && B.record ? ' checked' : ''}${ntOk ? '' : ' disabled'}><span>${esc(t('cal_book_record'))}</span></label><p class="help" aria-live="polite">${ntLine}</p></div>` : '';
  const loading = B.loading || !B.slots;
  const head = `<div class="cal-book-nav"><span class="cal-book-range">${esc(monthTitle(B.month))}</span><span class="cal-book-navbtns"><button type="button" class="btn btn-secondary btn-sm btn-icon" data-mnav="-1" aria-label="${esc(t('cal_book_month_prev'))}"${B.month <= todayIso.slice(0, 7) ? ' disabled' : ''}>${icon('chevron-left')}</button><button type="button" class="btn btn-secondary btn-sm btn-icon" data-mnav="1" aria-label="${esc(t('cal_book_month_next'))}">${icon('chevron-right')}</button></span></div>`;
  const cells = Array.from({ length: lead(B.month) }, () => '<span class="cal-book-dayb is-blank" aria-hidden="true"></span>').concat(monthDays().map(d => {
    const n = slotsOf(d).length, ok = bookable(d), on = d === B.date;
    return `<button type="button" class="cal-book-dayb${ok ? ' is-free' : ''}${on ? ' is-on' : ''}${d === todayIso ? ' is-today' : ''}" data-day="${d}"${ok ? '' : ' disabled'} aria-pressed="${on}" aria-label="${esc(fmtDay(d))}${ok ? ', ' + esc(n === 1 ? t('cal_book_one_time') : tf('cal_book_n_times', { n })) : ''}">${Number(d.slice(8, 10))}</button>`;
  })).join('');
  const grid = loading ? `<p class="help">${esc(t('cal_book_loading'))}</p>`
    : `<div class="cal-book-month" role="group" aria-label="${esc(t('cal_book_date'))}"><div class="cal-book-dows">${dows.map(w => `<span>${esc(w)}</span>`).join('')}</div><div class="cal-book-grid">${cells}</div>${monthDays().some(bookable) ? '' : `<p class="help">${esc(t('cal_book_none_month'))}</p>`}</div>`;
  const timeSel = field('cal-book-time', 'cal_book_time', `<select class="select" id="${p}-cal-book-time"${B.date ? '' : ' disabled'}><option value="">${esc(t('cal_book_time_ph'))}</option>${slotsOf(B.date).map(s => `<option value="${esc(s.start)}"${B.picked === s.start ? ' selected' : ''}>${esc(tf('cal_book_slot', { from: fmtTime(s.start), to: fmtTime(slotEnd(s)), ampm: fmtAmPm(s.start) }))}</option>`).join('')}</select>`);
  const when = `<div class="cal-book-sec">${head}${grid}${timeSel}<p class="help">${esc(tf('cal_book_zone', { zone, host: cal.cal_name || cal.cal_email || '' }))}</p></div>`;
  const conflict = !B.picked ? '' : B.checking ? `<p class="help">${esc(t('cal_book_checking'))}</p>`
    : B.conflicts.length ? `<div class="cal-book-conflict" role="alert">${B.conflicts.map(c => `<p>${esc(tf('cal_book_conflict', { time: c.time, title: c.title, who: c.who }))}</p>`).join('')}<p>${esc(t('cal_book_conflict_hint'))}</p></div>` : '';
  const note = `<div class="cal-book-sec">${field('cal-book-note', reschedule ? 'cal_resched_reason' : 'cal_book_note', `<textarea class="textarea" id="${p}-cal-book-note" rows="2" placeholder="${esc(t(reschedule ? 'cal_resched_reason_ph' : 'cal_book_note_ph'))}">${esc(B.note)}</textarea>`)}</div>`;
  const slot = B.picked ? slotsOf(B.date).find(x => x.start === B.picked) || { start: B.picked } : null;
  const summary = slot ? `<div class="cal-book-summary">${icon('calendar')}<div><b>${esc(fmtDay(B.date))}, ${esc(tf('cal_book_slot', { from: fmtTime(slot.start), to: fmtTime(slotEnd(slot)), ampm: fmtAmPm(slot.start) }))}</b><span>${esc([place ? placeLabel(place) : '', !reschedule && B.record && B.nt === 'ok' && isMeet(place) ? t('cal_book_record_short') : '', tf('cal_book_with', { name: contact.name })].filter(Boolean).join(', '))}</span></div></div>` : '';
  return `<p class="help">${esc(tf('cal_book_invite_to', { email: contact.email }))}</p>${what}${rec}${when}${conflict}${note}${summary}${B.err ? `<p class="cal-book-err" role="alert">${esc(B.err)}</p>` : ''}`;
}

// :346–347 the footer's go button: { disabled, text }
function krBookingGo(o) {
  const B = o.B, reschedule = o.reschedule || null;
  return { disabled: !!(!B.picked || B.busy || B.checking),
    text: B.busy ? t(reschedule ? 'cal_resched_busy' : 'cal_book_booking') : B.conflicts.length ? t('cal_book_anyway') : t(reschedule ? 'cal_resched_submit' : 'cal_book_submit') };
}

// :309 the footer, with the go button as render() leaves it. o.saveLocked: core.js:1385 adds
// 'is-save-locked' to a clicked .btn-primary for 1000 ms (so it shows during the first second of busy).
function krBookingFoot(o) {
  const g = krBookingGo(o);
  return `<button class="btn btn-secondary" data-close>${esc(t('btn_cancel'))}</button><button class="btn btn-primary${o.saveLocked ? ' is-save-locked' : ''}" id="${o.p}-cal-book-go"${g.disabled ? ' disabled' : ''}>${esc(g.text)}</button>`;
}

// core.js:1488+1492 (modal branch, size 'md') filled with :308 body and :309 footer
function krBookingDialog(o) {
  const p = o.p, id = `${p}-dlg`;
  return `<div class="overlay"><div class="modal md" role="dialog" aria-modal="true" aria-labelledby="${id}"><div class="modal-head"><h2 class="modal-title" id="${id}">${esc(krBookingTitle(o))}</h2><button class="iconbtn" data-close aria-label="${esc(t('btn_close'))}">${icon('x')}</button></div><div class="modal-body"><div id="${p}-cal-book" class="cal-book">${krBookingBody(o)}</div></div><div class="modal-foot">${krBookingFoot(o)}</div></div></div>`;
}

// ── the conflict rule (detail-views.js:373–393 checkConflicts) ──────────────────────────────────────────
// pickedStart: the slot start (ISO); slotEnd: its end (krBookingSlotEnd); zone: the viewer's zone;
// people: [booker users.id, cal.host_user_id]; rows: GET /api/calendar?start={day-1}&end={day+1};
// reschedule: the meeting being moved (its own activity row is skipped). → [{ time, title, who }]
function krBookingConflicts({ pickedStart, slotEnd, zone, people = [], rows = [], reschedule = null }) {
  const start = pickedStart; if (!start) return [];
  const sv = krBookingZonedParts(start, zone), ev = krBookingZonedParts(slotEnd, zone);
  const mins = hhmm => Number(hhmm.slice(0, 2)) * 60 + Number(hhmm.slice(3, 5));
  const s0 = mins(sv.time), s1 = ev.date === sv.date ? mins(ev.time) : 24 * 60;
  const who = new Set((people || []).filter(Boolean));
  const found = [];
  for (const e of Array.isArray(rows) ? rows : []) {
    if (!e.event_time || e.cancelled_at || e.completed || e.status === 'done' || !who.has(e.created_by)) continue;
    if (reschedule && e.kind !== 'task' && e.id === reschedule.id) continue;
    const v = krBookingToViewerClock(e.event_date, e.event_time, e.event_tz, zone);
    if (v.date !== sv.date) continue;
    const t0 = mins(v.time), t1 = t0 + 30;
    if (t0 < s1 && t1 > s0) found.push({ time: `${v.time} (${krBookingAmpmOf(v.time)})`, title: e.title || t('act_' + e.type), who: e.created_by_name || '' });
  }
  return found;
}

// ── the toasts after booking (detail-views.js:411–414) ──────────────────────────────────────────────────
// "Gebucht: Di., 27. Okt., 14:00 (2:00 PM). Cal.com schickt die Einladung." (reschedule + name: the move toast)
function krBookingDoneText({ picked, zone, reschedule = null, name = '' }) {
  const o = { zone };
  const when = `${krBookingFmtWhen(o, picked)} (${krBookingFmtAmPm(o, picked)})`;
  return reschedule ? tf('cal_resched_done', { when, name }) : tf('cal_book_done', { when });
}
// detail-views.js:261–265 dvNotetakerToast's text; null = no toast (the app shows none)
function krNotetakerToastText(n) {
  if (!n || !n.status) return null;
  const key = KR_BOOKING_NT_TOAST[n.status];
  return key ? t(key) : tf('cal_rec_failed', { error: n.error || t('cal_err_generic') });
}


/* ════ monitor ════ */
/* kr-monitor.js — replicas of the Onboarding monitor and the Integrations page's "Letzte Leads" tab
   (landing page two, Part 49). Concatenated after kr-core.js; uses its t / tf / esc / icon.
   Every renderer is a PORT of the app's own render code (cited file:line, repo state v2.3.2,
   2026-10-27). The template literals are copied verbatim; the only changes are the contract's:
     a. inline handlers removed — each becomes data-kr="<action>" (+ data-kr-arg="<value>")
        at the handler's place; nothing here is draggable;
     b. id="X" → id="${p}-X" (and aria-labelledby to it); sprite refs (#i-…) are NOT ids and stay;
     c. data-i18n attributes kept exactly; static text = t(key), serialised like a text node.
   Runtime state the app adds is baked in: `active` on the section (switchPage, auth.js:542), on the
   "Letzte Leads" tab and its pane (switchIntgTab, integrations.js:58-64). Class hooks kr-page-onboarding /
   kr-page-integrations stand in for the ID selectors of style.css (see kr-monitor.css).
   Pure: (data) → HTML string. No DOM, no timers, no fetch. kr-monitor.check.js proves A === B. */

// onboarding.js:20-22
const KR_ONB_STALE_DAYS = 14;      // "running" with no status change for this long gets a marker
const KR_ONB_STATUSES   = ['kein_onboarding', 'formular_versendet', 'formular_ausgefuellt', 'termin_gebucht', 'call_erfolgt', 'briefing_fertig', 'onboarding_abgeschlossen'];
const KR_ONB_FILTERS    = ['all', 'not_started', 'running', 'done'];

// How applyTranslations() (core.js:1069, el.textContent = t(key)) and `sub.textContent = …`
// (onboarding.js:76) serialise: a text node escapes & < > and U+00A0, never quotes.
function krTx(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/\u00a0/g, '&nbsp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// core.js:1156-1159 (fmtDate — not in kr-core)
function krFmtDate(dt) {
  if (!dt) return '';
  return new Date(dt).toLocaleDateString(currentLang === 'de' ? 'de-DE' : 'en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

/* ─────────────────────────── Onboarding monitor ─────────────────────────── */

// onboarding.js:39-45 (onboardingPhase): 'done' | 'running' | 'not_started'
function krOnboardingPhase(row) {
  if (!row) return 'not_started';
  if (row.onboarding_status === 'onboarding_abgeschlossen') return 'done';
  if (row.onboarding_status && row.onboarding_status !== 'kein_onboarding') return 'running';
  if (row.in_trigger || row.delivery) return 'running';
  return 'not_started';
}

// onboarding.js:47-50 (onboardingIsStale)
function krOnboardingIsStale(row, now = Date.now()) {
  if (krOnboardingPhase(row) !== 'running' || !row.status_since) return false;
  return now - new Date(row.status_since).getTime() > KR_ONB_STALE_DAYS * 86_400_000;
}

// onboarding.js:53 (onboardingStatusStep): 0 (kein_onboarding) … 6 (onboarding_abgeschlossen); unknown → 0
function krOnboardingStatusStep(status) { const i = KR_ONB_STATUSES.indexOf(status); return i < 0 ? 0 : i; }

// onboarding.js:72-73 — the segment counts, over ALL rows (independent of the active filter)
function krOnboardingCounts(rows) {
  rows = rows || [];
  const counts = { all: rows.length, not_started: 0, running: 0, done: 0 };
  rows.forEach(r => { counts[krOnboardingPhase(r)] += 1; });
  return counts;
}

// onboarding.js:147 — startOnboarding()'s guard: the confirm opens only when this is true
function krOnbCanStart(row) {
  return !(!row || row.in_trigger || !row.trigger_stage_id || row.contact_id == null);
}

// onboarding.js:88-141 (onboardingRowHtml). `now` only feeds the stale marker (app: Date.now()).
function krOnboardingRow(r, now = Date.now()) {
  const phase = krOnboardingPhase(r);
  const stale = krOnboardingIsStale(r, now);
  const dash  = '<span class="muted-dash">—</span>';
  const hasContact = r.contact_id != null;

  const stage = r.stage_name
    ? `<span class="stage-pill"><i style="background:${esc(r.stage_color || '#999')}"></i>${esc(r.stage_name)}</span>`
    : dash;

  const statusKey = KR_ONB_STATUSES.includes(r.onboarding_status) ? r.onboarding_status : 'kein_onboarding';
  const status = hasContact
    ? `<span class="onb-status step-${krOnboardingStatusStep(r.onboarding_status)}${phase === 'done' ? ' done' : ''}">${esc(t('onb_status_' + statusKey))}</span>`
    : dash;

  const since = hasContact && r.status_since
    ? `${esc(krFmtDate(r.status_since))}${stale ? ` <span class="badge badge-warning">${esc(tf('onb_stale', { days: KR_ONB_STALE_DAYS }))}</span>` : ''}`
    : '';

  const d = r.delivery;
  const dStatus = d && ['success', 'failed', 'pending'].includes(d.status) ? d.status : 'pending';
  const delivery = !d
    ? `<span class="muted">${esc(t('onb_delivery_none'))}</span>`
    : `<span class="badge ${dStatus === 'success' ? 'badge-success' : dStatus === 'failed' ? 'badge-danger' : 'badge-warning'}" title="${esc(d.last_error || '')}">${esc(t('engine_status_' + dStatus))}</span>`;

  const drive = r.drive_ordner_id
    ? `<a class="onb-drive" href="https://drive.google.com/drive/folders/${encodeURIComponent(r.drive_ordner_id)}" target="_blank" rel="noopener" title="${esc(t('onb_drive_link'))}" aria-label="${esc(t('onb_drive_link'))}">${icon('folder')}</a>`
    : '';

  let action = '';
  if (phase === 'not_started' && !r.in_trigger) {
    const why = !hasContact ? t('onb_no_contact') : !r.trigger_stage_id ? t('onb_no_trigger_stage') : '';
    action = why
      ? `<button type="button" class="btn btn-secondary btn-sm" disabled title="${esc(why)}">${esc(t('onb_btn_start'))}</button>`
      : `<button type="button" class="btn btn-primary btn-sm" data-kr="onb-start" data-kr-arg="${Number(r.deal_id)}">${esc(t('onb_btn_start'))}</button>`;
  }

  const customer = hasContact
    ? `<a href="#" data-kr="onb-open-contact" data-kr-arg="${Number(r.contact_id)}">${esc(r.contact_name)}</a>${r.contact_company ? `<div class="muted onb-sub">${esc(r.contact_company)}</div>` : ''}`
    : dash;

  return `<tr data-deal="${Number(r.deal_id)}">
    <td class="strong"><a href="#" data-kr="onb-open-deal" data-kr-arg="${Number(r.deal_id)}">${esc(r.deal_title)}</a><div class="muted onb-sub">${esc(r.pipeline_name || '')}</div></td>
    <td>${customer}</td>
    <td>${stage}</td>
    <td>${status}</td>
    <td>${since}</td>
    <td>${delivery}</td>
    <td>${drive}</td>
    <td class="onb-actions">${action}</td>
  </tr>`;
}

// onboarding.js:77-79 — the content of #onboarding-toolbar (the four filter segments)
function krOnboardingToolbar(rows, filter = 'all') {
  const counts = krOnboardingCounts(rows);
  return `<div class="seg" role="group" aria-label="${esc(t('onb_filter_aria'))}">${
    KR_ONB_FILTERS.map(f => `<button type="button" aria-pressed="${f === filter}" data-kr="onb-filter" data-kr-arg="${f}">${esc(t('onb_filter_' + f))} <span class="muted">${counts[f]}</span></button>`).join('')
  }</div>`;
}

// onboarding.js:81-84 — the content of #onboarding-body (rows, or the empty row)
function krOnboardingBody(rows, filter = 'all', now = Date.now()) {
  rows = rows || [];
  const shown = rows.filter(r => filter === 'all' || krOnboardingPhase(r) === filter);
  return shown.length
    ? shown.map(r => krOnboardingRow(r, now)).join('')
    : `<tr class="table-empty-row"><td colspan="8"><div class="table-empty"><h2>${esc(t(rows.length ? 'onb_empty_filter' : 'onb_empty'))}</h2><p>${esc(t('onb_empty_hint'))}</p></div></td></tr>`;
}

// The whole page: index.html:1070-1097 + what renderOnboarding() (onboarding.js:66-85) puts in it.
//   o.p       id prefix (default 'kr')
//   o.rows    GET /api/engine/onboarding → .rows   (null/undefined = no data, like an error answer)
//   o.active  GET /api/engine/onboarding → .active (default true; false shows the "switched off" hint)
//   o.filter  'all' | 'not_started' | 'running' | 'done' (anything else → 'all', onboarding.js:62)
//   o.now     clock for the stale marker (default Date.now())
function krOnboardingPage(o = {}) {
  const p      = esc(o.p ?? 'kr');
  const data   = o.rows == null ? null : { active: o.active !== false, rows: o.rows };
  const rows   = data?.rows || [];
  const filter = KR_ONB_FILTERS.includes(o.filter) ? o.filter : 'all';
  const now    = o.now ?? Date.now();
  const counts = krOnboardingCounts(rows);
  const hintHidden = !data || !!data.active;   // onboarding.js:75
  return `<section id="${p}-page-onboarding" class="page active kr-page-onboarding">
        <div class="page-header">
          <div>
            <h1 class="page-title"><svg class="ic" aria-hidden="true"><use href="#i-target"/></svg><span data-i18n="nav_onboarding">${krTx(t('nav_onboarding'))}</span></h1>
            <p class="page-sub" id="${p}-onboarding-page-sub">${krTx(tf('onb_sub', { running: counts.running, done: counts.done }))}</p>
          </div>
          <div class="page-actions">
            <button class="btn btn-secondary btn-sm" type="button" data-kr="onb-refresh"><svg class="ic ic-sm" aria-hidden="true"><use href="#i-refresh"/></svg><span data-i18n="btn_refresh">${krTx(t('btn_refresh'))}</span></button>
          </div>
        </div>
        <p class="onb-inactive${hintHidden ? ' hidden' : ''}" id="${p}-onboarding-inactive" data-i18n="onb_inactive_hint">${krTx(t('onb_inactive_hint'))}</p>
        <div class="toolbar" id="${p}-onboarding-toolbar">${krOnboardingToolbar(rows, filter)}</div>
        <div class="table-wrap">
          <table class="table" id="${p}-onboarding-table">
            <thead><tr>
              <th data-i18n="onb_col_deal">${krTx(t('onb_col_deal'))}</th>
              <th data-i18n="onb_col_customer">${krTx(t('onb_col_customer'))}</th>
              <th data-i18n="onb_col_stage">${krTx(t('onb_col_stage'))}</th>
              <th data-i18n="onb_col_status">${krTx(t('onb_col_status'))}</th>
              <th data-i18n="onb_col_since">${krTx(t('onb_col_since'))}</th>
              <th data-i18n="onb_col_delivery">${krTx(t('onb_col_delivery'))}</th>
              <th data-i18n="onb_col_drive">${krTx(t('onb_col_drive'))}</th>
              <th class="onb-actions" data-i18n="onb_col_actions">${krTx(t('onb_col_actions'))}</th>
            </tr></thead>
            <tbody id="${p}-onboarding-body">${krOnboardingBody(rows, filter, now)}</tbody>
          </table>
        </div>
      </section>`;
}

// The "Onboarding starten?" dialog exactly as startOnboarding() (onboarding.js:148-152) opens it through
// ui.confirm (core.js:1516-1522) → ui.modal → uiOverlay (core.js:1486-1491, modal branch, size 'sm').
//   o.p    id prefix; o.row  the onboarding row (deal_title, trigger_stage_name)
//   o.uid  the dialog id's random part (app: uid(), 7 chars) — default 'onbstart'
// Returns the .overlay element (the app appends it to <body>).
function krOnbConfirm(o = {}) {
  const p = esc(o.p ?? 'kr');
  const row = o.row || {};
  const title = t('onb_confirm_title');
  const message = tf('onb_confirm_body', { deal: row.deal_title, stage: row.trigger_stage_name || '' });
  const confirmLabel = t('onb_btn_start'), cancelLabel = t('btn_cancel'), danger = false;
  const size = 'sm';
  const id = `${p}-dlg-${esc(o.uid ?? 'onbstart')}`;
  const body = `<p class="sub">${esc(message)}</p>`;
  const footer = `<button class="btn btn-secondary" data-no>${esc(cancelLabel)}</button><button class="btn ${danger ? 'btn-danger' : 'btn-primary'}" data-yes>${esc(confirmLabel)}</button>`;
  return `<div class="overlay"><div class="modal ${size}" role="dialog" aria-modal="true" aria-labelledby="${id}"><div class="modal-head"><h2 class="modal-title" id="${id}">${esc(title)}</h2><button class="iconbtn" data-close aria-label="${esc(t('btn_close'))}">${icon('x')}</button></div><div class="modal-body">${body}</div>${footer ? `<div class="modal-foot">${footer}</div>` : ''}</div></div>`;
}

// One .toast as ui.toast() (core.js:1523-1529) builds it after startOnboarding (onboarding.js:155-156).
//   { row }    → success: „Onboarding für „{deal}“ gestartet"
//   { error }  → failure: the server's error text, or t('core_network_error') when there is none
// The app puts it into one shared <div class="toasts" role="status" aria-live="polite"> on <body>.
function krOnbToast(o = {}) {
  const message = 'error' in o ? (o.error || t('core_network_error')) : tf('onb_started_toast', { deal: (o.row || {}).deal_title });
  return `<div class="toast"><span>${esc(message)}</span></div>`;
}

/* ─────────────────────── Integrations · "Letzte Leads" ─────────────────────── */

// integrations.js:516-540 — one entry of GET /api/integrations/logs → .logs
function krLeadLogRow(l) {
  const skipped  = l.captured?._skipped || {};
  const hasSkips = Object.keys(skipped).length > 0;
  const captured = { ...l.captured };
  delete captured._skipped;

  return `<div class="intg-log-entry${l.status === 'error' ? ' error' : ''}">
      <div class="intg-log-entry-header">
        <span class="intg-log-badge ${l.status}">${esc(t('intg_log_' + l.status))}</span>
        <span class="intg-log-time">${new Date(l.created_at).toLocaleString(currentLang === 'de' ? 'de-DE' : 'en-GB')}</span>
        <span class="intg-log-contact">${l.contact_name ? esc(l.contact_name) : (l.error ? esc(l.error) : '—')}</span>
      </div>
      ${l.status === 'success' ? `
        <div class="intg-log-fields">
          ${Object.entries(captured).filter(([,v]) => v).map(([k, v]) =>
            `<span class="intg-log-field"><span class="intg-log-field-key">${esc(k)}</span>${esc(String(v))}</span>`
          ).join('')}
        </div>
        ${hasSkips ? `<div class="intg-log-skipped">
          ${esc(t('intg_fields_missing'))} ${Object.keys(skipped).map(k => `<code>${esc(k)}</code>`).join(', ')}
          ${esc(t('intg_fields_missing_hint'))}
        </div>` : ''}` : ''}
      <div class="intg-log-raw-toggle" data-kr="intg-raw-toggle">${esc(t('intg_view_raw'))}</div>
      <pre class="intg-log-raw hidden">${esc(JSON.stringify(l.payload || {}, null, 2))}</pre>
    </div>`;
}

// integrations.js:508-515 + 541 — the content of #intg-logs (entries, or the empty line; null = error answer)
function krLeadLogs(logs) {
  if (!logs || !logs.length) return `<p class="empty-inline">${esc(t('intg_no_activity'))}</p>`;
  return logs.map(krLeadLogRow).join('');
}

// The Integrations page with "Letzte Leads" open: index.html:1099-1121 (header, rail) + 1211-1230 (its pane)
