            <div class="settings-pane-head">
              <h2 class="settings-pane-title" data-i18n="intg_pane_activity">${krTx(t('intg_pane_activity'))}</h2>
              <p class="settings-tab-hint" data-i18n="intg_pane_activity_hint">${krTx(t('intg_pane_activity_hint'))}</p>
            </div>
